/* Câu chép chính tả: khung phát (giây) trong audio từng part, lấy theo mốc lời thoại (sync.js); chỉ giữ câu mà chữ nghe được khớp lời thoại ≥ 80%. 26/10/2026 */
window.CAMDICT={"1":{"1":[{"s":20.43,"e":22.37,"t":"Hello, Clarence House."},{"s":32.17,"e":34.81,"t":"Can I ask what date you were thinking of?"},{"s":34.51,"e":38.23,"t":"Either the 1st or the 7th of June?"},{"s":38.59,"e":41.01,"t":"Right, let me see."},{"s":51.77,"e":54.79,"t":"So, how many guests are you going to be inviting?"},{"s":60.81,"e":62.99,"t":"I don't know if you've been to the hotel?"},{"s":63.11,"e":69.17,"t":"Yes, in fact, I went to a wedding there a few years ago and I was really impressed."},{"s":70.57,"e":73.41,"t":"I think we were in the Oxford Suite then."},{"s":73.65,"e":78.79,"t":"The room where we were eating had big windows with really good views."},{"s":79.05,"e":81.03,"t":"You could see right across the city."},{"s":82.95,"e":85.93,"t":"And you'd have exclusive access to the garden."},{"s":86.31,"e":88.25,"t":"It'll be at its best in June."},{"s":88.29,"e":90.49,"t":"So, we could have the photos there?"},{"s":91.61,"e":94.95,"t":"In fact, you can even have the ceremony there if you want."},{"s":95.21,"e":97.03,"t":"It makes a lovely background."},{"s":97.21,"e":99.15,"t":"Oh, I hadn't thought of that."},{"s":99.53,"e":101.91,"t":"Yes, that's certainly an idea."},{"s":102.41,"e":104.97,"t":"And is there somewhere for dancing?"},{"s":105.15,"e":109.33,"t":"Yes, there's plenty of space in the middle of the dining room."},{"s":109.39,"e":111.42,"t":"Oh yeah, I remember now."},{"s":111.95,"e":118.25,"t":"So, just to give you an idea, would you like me to tell you about our special wedding package?"},{"s":133.41,"e":135.23,"t":"And how's the room arranged?"},{"s":135.61,"e":138.12,"t":"I seem to remember you have round tables?"},{"s":139.67,"e":142.25,"t":"Most people prefer them to long tables."},{"s":142.19,"e":145.29,"t":"Long tables aren't really very friendly, are they?"},{"s":145.95,"e":148.89,"t":"And what about decorations on the tables?"},{"s":149.05,"e":150.87,"t":"They're included in the package."},{"s":151.11,"e":155.01,"t":"And we have white linen tablecloths and white chair covers."},{"s":155.71,"e":160.61,"t":"And we also include an individually designed menu specially printed for you."},{"s":161.05,"e":164.41,"t":"It's something that people can take away to remember the occasion."},{"s":165.01,"e":167.63,"t":"That's something we've just started doing this year."},{"s":217.92,"e":223.52,"t":"Nothing too complicated, just a selection of sandwiches together with tea or coffee."},{"s":223.86,"e":225.68,"t":"That's always very popular."},{"s":227.48,"e":229.06,"t":"And we'll want some music."},{"s":229.16,"e":231.0,"t":"Is that included in the package?"},{"s":231.12,"e":234.84,"t":"No, but we could probably get you a DJ."},{"s":235.44,"e":238.82,"t":"Or we know of a very good band if you'd prefer that."},{"s":238.82,"e":241.5,"t":"Yes, that'd be better actually."},{"s":241.2,"e":243.94,"t":"Something to get everyone on their feet."},{"s":245.56,"e":250.36,"t":"So, apart from the music, you said that's an all-inclusive package."},{"s":250.92,"e":254.0,"t":"So, how much does that package come to?"},{"s":258.9,"e":263.02,"t":"That's a bit more than the package they quoted for me at the Stanley Hotel."},{"s":267.06,"e":272.96,"t":"But I think if you look at what you're getting for the money, you'll find we're the best value."},{"s":273.64,"e":275.66,"t":"And it is a big day after all."},{"s":275.46,"e":277.78,"t":"Yes, you're probably right."},{"s":278.14,"e":280.2,"t":"Oh, and I nearly forgot."},{"s":280.54,"e":284.46,"t":"I'm looking for someone who can make me a really special cake."},{"s":284.72,"e":286.08,"t":"Can you suggest one?"},{"s":287.46,"e":290.02,"t":"There's a new company that we've started using."},{"s":290.04,"e":291.46,"t":"They're very good."},{"s":291.88,"e":296.48,"t":"In fact, our wedding coordinator will be able to give you all sorts of advice."},{"s":297.08,"e":301.04,"t":"We can offer you a free consultation and a tour of the venue."},{"s":301.06,"e":304.14,"t":"Yes, well, I'd definitely be interested."},{"s":313.7,"e":317.02,"t":"Now, when would you like to meet her?"},{"s":317.52,"e":323.78,"t":"She's available from nine to five most weekdays, or later if that's more convenient."},{"s":324.88,"e":332.38,"t":"I'm free on the 12th of October, in the morning sometime, or the 15th of October."},{"s":332.92,"e":334.86,"t":"That would be better, thanks."},{"s":338.44,"e":341.66,"t":"And can I just take your name and a contact number?"}],"2":[{"s":55.22,"e":61.8,"t":"Welcome, everyone, to this farmers' and growers' market in the quiet village of Havelock North."},{"s":62.32,"e":65.52,"t":"My name is Helen, and I'm your guide for the morning."},{"s":82.68,"e":86.1,"t":"Right, so what do people sell here?"},{"s":86.58,"e":93.78,"t":"Well, for a start, there's some very nice hand cream from the Far North, which is always a top seller abroad."},{"s":120.62,"e":122.84,"t":"Still, very delicious though."},{"s":142.54,"e":146.98,"t":"Ah, now there are the candles for sale at a very reasonable price."},{"s":147.58,"e":152.54,"t":"They probably represent the top buy if you want your dollar to stretch as far as possible."},{"s":153.48,"e":160.86,"t":"They're just the colour of wax, so that's not too exciting, but they do come in all different sizes to suit different purposes."},{"s":162.5,"e":165.22,"t":"Just a couple more items for me to tell you about."},{"s":165.56,"e":168.18,"t":"There's great flavoured ice cream on offer."},{"s":168.44,"e":176.96,"t":"In fact, it's so good that it's classified export grade and was awarded the gold medal at this year's food fair."},{"s":176.66,"e":178.78,"t":"You should try some."},{"s":179.36,"e":187.86,"t":"And finally, we've got shampoo, which comes in cute little blue, green and red bottles for three different hair types."},{"s":188.5,"e":197.02,"t":"The best thing about this product is that it's produced right here in Havelock North Village by a farmer's wife who started her own company."},{"s":233.18,"e":238.62,"t":"Right, so that's given you an idea of the sorts of products which are on sale at this market."},{"s":239.02,"e":243.64,"t":"Now, let's just give you a quick rundown on where to find everything."},{"s":243.98,"e":246.5,"t":"Then I'll let you go for a walk around to do your shopping."},{"s":273.6,"e":279.82,"t":"There are some lovely toys for sale there, and also hand-carved wooden platters and bowls."},{"s":297.34,"e":299.74,"t":"Oh yes, the wool shop."},{"s":310.94,"e":313.52,"t":"There are some nice scarves and hats there too."},{"s":313.92,"e":317.84,"t":"Now after all this shopping you'll be needing a drink and something to eat."},{"s":317.66,"e":325.76,"t":"So go into the circular stand in the middle and you'll find a stall selling local wine, fruit juices and cordials."},{"s":335.24,"e":337.76,"t":"Well, that's all from me, folks."},{"s":338.1,"e":339.84,"t":"Now, enjoy the market."}],"3":[{"s":65.38,"e":66.74,"t":"Where's everybody else?"},{"s":67.84,"e":69.3,"t":"You're the first to get here."},{"s":69.4,"e":71.46,"t":"Well, I hope they don't take too long."},{"s":73.0,"e":76.5,"t":"Why don't we at least discuss what we've completed and what's left to do?"},{"s":78.02,"e":79.76,"t":"Have you heard anything from Irene?"},{"s":80.3,"e":84.16,"t":"Yeah, Irene told me the experiment is just about done."},{"s":84.58,"e":87.52,"t":"She's been practically living in the lab the past week."},{"s":87.48,"e":90.26,"t":"Wow, we owe her a favour, don't we?"},{"s":90.18,"e":91.94,"t":"You can say that again."},{"s":92.14,"e":93.56,"t":"Has Kim been helping her?"},{"s":93.74,"e":96.18,"t":"I thought that lab work was not her style."},{"s":96.52,"e":101.68,"t":"Well, not so much in the lab, but she has started compiling the data for the analysis."},{"s":101.86,"e":103.24,"t":"Kim is terrific."},{"s":105.14,"e":107.0,"t":"I've always been bad at math."},{"s":107.2,"e":110.96,"t":"I always thought there wasn't anything to that boys are good at math theory."},{"s":111.34,"e":113.46,"t":"Yes, and I’m a proof."},{"s":114.2,"e":121.24,"t":"Anyway, Kim hasn't actually run the stats for the project yet, since she still has to wait for the rest of the experiment data."},{"s":121.72,"e":125.0,"t":"But she's ready to get started when we get the experiment done."},{"s":125.88,"e":129.0,"t":"Seriously, without Irene and Kim, we'd be in trouble."},{"s":128.7,"e":130.66,"t":"Yeah, you're right about that."},{"s":131.2,"e":132.94,"t":"So what about Linda?"},{"s":135.66,"e":138.22,"t":"All she ever talks about is her fiancé."},{"s":138.5,"e":141.2,"t":"I haven't seen or heard from her all week."},{"s":141.48,"e":143.46,"t":"Well, I hope she turns up soon."},{"s":143.42,"e":145.98,"t":"We'll need everyone if we're going to get this done on time."},{"s":145.98,"e":150.18,"t":"Yeah, and she knows that Professor Cooper is a hard grader of projects."},{"s":150.9,"e":155.1,"t":"I'm worried that Professor Cooper is not going to give us a passing grade."},{"s":154.8,"e":158.46,"t":"Anyway, we haven't talked about the introduction yet."},{"s":158.76,"e":161.94,"t":"Have you finished reading those articles Professor Cooper gave us?"},{"s":162.38,"e":165.88,"t":"Bill, she gave us those two weeks ago."},{"s":165.7,"e":167.26,"t":"Hey, I've been busy."},{"s":168.82,"e":170.18,"t":"Come on, Bill."},{"s":170.3,"e":173.9,"t":"Jen, you know we all depend on you for that."},{"s":174.24,"e":177.92,"t":"You're the only person I know that reads every assignment from beginning to end."},{"s":178.5,"e":183.42,"t":"You and Professor Cooper often have private discussions about readings in the middle of class."},{"s":185.9,"e":188.78,"t":"That's why all the rest of us asked you to be on our team."},{"s":188.66,"e":190.62,"t":"Oh, so that's why."},{"s":190.84,"e":193.26,"t":"So it wasn't because I'm popular, huh?"},{"s":193.18,"e":194.92,"t":"Hey, you're the best."},{"s":195.04,"e":196.38,"t":"No one's going to argue that."},{"s":196.42,"e":197.98,"t":"Hey, I'm thirsty."},{"s":200.5,"e":202.14,"t":"Okay, I'll be right back."},{"s":246.4,"e":248.14,"t":"And I've got a class I got to get to."},{"s":249.0,"e":253.56,"t":"Well, let's divide up responsibilities, like who's responsible for each section."},{"s":253.94,"e":260.16,"t":"It only makes sense that Irene writes up all the materials and methods since she spent the most time with that."},{"s":261.5,"e":263.72,"t":"Hey, didn't you just say we owe her one?"},{"s":263.68,"e":265.16,"t":"Yeah, yeah, you're right."},{"s":265.46,"e":267.34,"t":"Irene can do the methodology section."},{"s":276.46,"e":279.22,"t":"And besides, you are the one good at copy editing."},{"s":279.28,"e":283.82,"t":"Well, all the same, I think it'll be easiest if she does the results section."},{"s":285.3,"e":288.3,"t":"Come on, that's asking a lot of you."},{"s":288.38,"e":290.42,"t":"Well, what part are you going to do, Jen?"},{"s":290.44,"e":291.84,"t":"Isn't that obvious?"},{"s":292.04,"e":294.24,"t":"Since I'm the one who does all the reading."},{"s":293.94,"e":297.24,"t":"I'm sure you'll give us the best literature review, Jen."},{"s":297.3,"e":298.74,"t":"We're all counting on you for that."},{"s":302.6,"e":304.56,"t":"Yeah, can you make suggestions on these?"},{"s":304.96,"e":309.98,"t":"Okay, but seriously, wouldn't it make more sense if you do the list of references?"},{"s":310.2,"e":314.9,"t":"There are enough commas, capital letters, and parentheses to keep you happy in there."},{"s":315.34,"e":316.9,"t":"Yeah, you got a point."},{"s":325.56,"e":328.32,"t":"Yeah, but isn't that like the most important section?"},{"s":328.38,"e":330.64,"t":"Well, what else is she going to do?"},{"s":330.46,"e":331.86,"t":"The whole paper."},{"s":331.78,"e":333.12,"t":"It'll serve her right."},{"s":333.32,"e":334.74,"t":"Then we'd all fail."},{"s":334.9,"e":339.06,"t":"Okay, but I think we all should start messaging her to make sure she gets busy."},{"s":341.84,"e":343.28,"t":"What about the abstract?"},{"s":343.44,"e":346.4,"t":"You really don't want me to do the abstract, do you?"}],"4":[{"s":72.37,"e":73.79,"t":"Good morning, everyone."},{"s":74.49,"e":79.39,"t":"Today, in this second lecture of the series, we turn our attention to transportation."},{"s":100.51,"e":103.77,"t":"But let's go back for a while to the late 1940s."},{"s":137.07,"e":140.55,"t":"Remember, this wasn't long after the Second World War."},{"s":140.91,"e":147.37,"t":"People were tired of living without things, of making do, and to them, cars represented freedom."},{"s":147.91,"e":153.93,"t":"But even for the wealthy few who did have vehicles, it wasn't easy to run a car at this time."},{"s":154.35,"e":160.93,"t":"As well as the expense of buying a car, spare parts were difficult to get, as many were imported."},{"s":161.25,"e":167.87,"t":"Another problem for car owners was that fuel was still rationed, and car taxes were very high."},{"s":186.86,"e":195.14,"t":"In the 1960s, cheaper, more reliable cars became available, and this coincided with the rapid expansion of the suburbs."},{"s":195.46,"e":202.36,"t":"The car enabled these to grow in all directions, far beyond the train lines laid down in the 19th century."},{"s":203.06,"e":212.06,"t":"For the previous 150 years, the city centre had been a prestigious area, but the addition of cars made the main streets congested."},{"s":212.18,"e":214.14,"t":"This wasn't the only problem."},{"s":214.42,"e":216.4,"t":"Now they were polluted as well."},{"s":216.5,"e":221.46,"t":"Since these streets were usually straight, they tempted motorists to speed."},{"s":222.06,"e":227.44,"t":"So the layout of newer streets was affected by this change towards private transport."},{"s":227.78,"e":231.84,"t":"In the newer areas, roads were no longer built straight."},{"s":231.68,"e":237.4,"t":"Instead, they had curves that were specially designed to force drivers to slow down."},{"s":237.8,"e":242.96,"t":"This meant they were longer, but this was not a problem because people rarely walked anymore."},{"s":243.58,"e":250.36,"t":"By the 1970s, the type of roads being built changed, with more lanes in each direction."},{"s":250.9,"e":255.84,"t":"There were more commuters, because now there was faster access to the city where they worked."},{"s":256.48,"e":260.94,"t":"By this time, the motor car was affecting many different areas of life."},{"s":260.66,"e":264.86,"t":"It even, surprisingly, affected relationships."},{"s":265.58,"e":272.24,"t":"Before this, meeting anyone who lived beyond walking or cycling distance was impractical, if not impossible."},{"s":272.68,"e":274.84,"t":"The car brought people together."},{"s":275.62,"e":278.34,"t":"What other effects did the car have?"},{"s":279.12,"e":282.26,"t":"The increase in car use changed the way we advertise."},{"s":282.76,"e":291.72,"t":"Previously, advertisements had been designed to attract slow-moving pedestrians, so they were located at eye level and designed on a human scale."},{"s":292.32,"e":299.0,"t":"By the late 1970s, massive advertisements were designed to attract the notice of the passing motorist."},{"s":299.82,"e":304.9,"t":"In the 1980s and 90s, even the location of shops began to change."},{"s":305.64,"e":311.52,"t":"We built shopping malls out in the suburbs, which meant that old town centres did far less business."},{"s":321.66,"e":326.98,"t":"Now, I'd like to turn your attention to a few statistics related to car ownership..."}]},"2":{"1":[{"s":109.29,"e":113.15,"t":"I saw an advert for holiday staff on the notice board and I'm very interested."},{"s":113.61,"e":115.45,"t":"Can you tell me something about the resort?"},{"s":115.67,"e":117.31,"t":"Let me see."},{"s":117.33,"e":120.51,"t":"Yes, those jobs are at the Sandy Shores Resort."},{"s":120.97,"e":124.13,"t":"You may have heard of it as it's quite well known in the area."},{"s":123.83,"e":134.12,"t":"The name of the resort is Sandy Shores, so Sandy has been written in the space."},{"s":151.36,"e":155.14,"t":"I saw an advert for holiday staff on the notice board and I'm very interested."},{"s":154.84,"e":157.42,"t":"Can you tell me something about the resort?"},{"s":159.28,"e":162.56,"t":"Yes, those jobs are at the Sandy Shores Resort."},{"s":162.94,"e":166.08,"t":"You may have heard of it as it's quite well known in the area."},{"s":166.26,"e":167.72,"t":"I'm not sure."},{"s":167.62,"e":168.94,"t":"Where exactly is it?"},{"s":170.86,"e":172.28,"t":"I haven't heard of that one."},{"s":171.98,"e":174.02,"t":"How do you spell it?"},{"s":179.34,"e":181.58,"t":"It was named after a famous explorer."},{"s":181.6,"e":183.14,"t":"Oh, sounds interesting."},{"s":183.4,"e":189.84,"t":"Yes, it's a beautiful place and as it's a large resort they have vacancies in a few different areas."},{"s":190.2,"e":192.0,"t":"When would they want someone to start?"},{"s":192.4,"e":199.34,"t":"It looks like the applications close by the 12th of May and they would need you to begin from the 11th of July."},{"s":200.62,"e":202.46,"t":"My exams finish on the 5th of July."},{"s":202.88,"e":204.76,"t":"Can you tell me something about the jobs?"},{"s":205.12,"e":209.76,"t":"Well, first of all, there is a vacancy in the Calypso Bistro."},{"s":211.44,"e":215.24,"t":"The work is quite easy, taking orders and serving meals."},{"s":215.68,"e":218.62,"t":"You don't need any experience as they will train you."},{"s":219.0,"e":225.2,"t":"They've also got a few vacancies in what is called the Guest Liaison Department."},{"s":225.74,"e":231.6,"t":"They are involved with the entertainment in the resort, especially the daily music shows and parades."},{"s":231.68,"e":234.46,"t":"They definitely need people who can sing."},{"s":235.98,"e":239.08,"t":"It's shocking, but I can play piano."},{"s":240.4,"e":241.76,"t":"I don't think so."},{"s":242.08,"e":243.7,"t":"They already have a band."},{"s":244.1,"e":246.28,"t":"So what else is there?"},{"s":246.24,"e":254.86,"t":"Among the most popular things for guests are the games and water sports activities, which take place on the beach that belongs to the resort."},{"s":265.52,"e":268.26,"t":"Well, I coach junior basketball."},{"s":270.52,"e":273.3,"t":"Finally, there are vacancies in the reception area."},{"s":273.58,"e":279.18,"t":"You'd work as part of the concierge department, carrying bags to and from rooms."},{"s":279.5,"e":282.58,"t":"A requirement for this role is that you can drive."},{"s":329.84,"e":334.3,"t":"I expect you'd like to know a bit more about the general benefits for staff."},{"s":335.42,"e":337.66,"t":"Do they provide free accommodation for staff?"},{"s":351.04,"e":352.8,"t":"What about meals?"},{"s":352.8,"e":359.24,"t":"Yes, they're provided when you're on duty, so you would save money on groceries."},{"s":359.72,"e":362.92,"t":"If you are interested, we can set up an interview for you."},{"s":363.3,"e":370.08,"t":"I know the resort personnel manager wants interviews on Wednesday, Thursday and Friday here at the college."},{"s":371.68,"e":374.54,"t":"Can we do it on Thursday as I work on Wednesdays?"},{"s":379.14,"e":381.02,"t":"I've booked you in for then."},{"s":381.04,"e":383.18,"t":"Is there anything I need to take to the interview?"},{"s":383.32,"e":384.66,"t":"Let me see."},{"s":400.62,"e":401.98,"t":"Do you have any questions?"}],"2":[{"s":65.86,"e":73.1,"t":"Today we are pleased to welcome Peter Gentle, who is organizing this year's famous Tavie Point Walk."},{"s":73.34,"e":75.8,"t":"Can you tell us about the walk, Peter?"},{"s":95.74,"e":98.06,"t":"The walk is mainly aimed at families."},{"s":98.46,"e":101.0,"t":"We want to help people to walk with their children."},{"s":101.3,"e":105.92,"t":"It's healthy exercise and it helps people get to know their local area better."},{"s":106.56,"e":114.12,"t":"Now for those of your listeners who might be interested in doing the walk, it takes place this year on Sunday the 27th of October."},{"s":114.74,"e":121.54,"t":"It's 18 miles in length, so quite long, but we ensure walkers are very well looked after."},{"s":121.86,"e":126.96,"t":"We like to involve as many people as possible and it's getting busier every year."},{"s":139.28,"e":141.88,"t":"You provide a lot of support then."},{"s":142.02,"e":147.74,"t":"We have to be pretty strict about arrangements, but we do what we can to help people."},{"s":148.06,"e":153.68,"t":"If someone arrives without proper clothing, we can help out from our stocks of waterproofs, for example."},{"s":153.38,"e":155.66,"t":"We don't just turn them away."},{"s":156.5,"e":160.08,"t":"The only time we do that is if people behave badly at the start."},{"s":160.62,"e":168.08,"t":"We also spend a lot of time fielding walkers questions about safety, both before the walk and while it's going on."},{"s":168.34,"e":171.58,"t":"Do you ever cancel the walk for very bad weather?"},{"s":171.56,"e":175.52,"t":"Yes, but it hasn't happened for several years."},{"s":185.04,"e":189.14,"t":"The team felt really awful about it, but these things happen."},{"s":189.98,"e":194.44,"t":"If something does go amiss, we try to inform all walkers well in advance."},{"s":195.44,"e":206.54,"t":"If any of your listeners are interested in joining the walk, they should go to our website at www.tvwalk.org and give us their details."},{"s":207.04,"e":213.14,"t":"It costs £4.50 each to enter, and that covers a bottle of juice and a hot pie."},{"s":213.38,"e":218.5,"t":"It also helps towards maintaining the 12 staff checkpoints at different parts on the route."},{"s":232.36,"e":236.44,"t":"If you do complete the course, you are entitled to receive a badge."},{"s":236.14,"e":241.36,"t":"Now, unfortunately, we can't give those to you immediately on finishing."},{"s":250.9,"e":257.18,"t":"It may seem a strange system, but we found it works because only those walkers who really want a badge get one."},{"s":299.64,"e":302.24,"t":"What do walkers need to take with them?"},{"s":313.06,"e":318.32,"t":"Now, it must be emphasised that this doesn't mean that you wear thick trousers like jeans."},{"s":318.7,"e":321.56,"t":"Lighter, waterproof apparel is better."},{"s":327.52,"e":331.42,"t":"And remember, the checkpoints are there, so you can always rely on those."},{"s":332.26,"e":337.44,"t":"Some people asked if they should bring a torch, but frankly, they're a waste of space and weight."},{"s":337.86,"e":341.18,"t":"It's a relatively gentle, straightforward walk."},{"s":341.72,"e":344.62,"t":"Another thing people ask about is refreshments."},{"s":345.04,"e":348.48,"t":"Whether you carry things like high-energy drinks is up to you."},{"s":348.18,"e":355.62,"t":"And finally, we say it's a very good idea to bring a rucksack, but what size is up to the individual."},{"s":356.02,"e":359.56,"t":"But as I say, there's full information in the walker's booklet."},{"s":359.82,"e":361.76,"t":"Well, thank you very much, Peter."}],"3":[{"s":64.4,"e":66.3,"t":"Shall we get down to planning our assignment?"},{"s":69.6,"e":72.78,"t":"And it's quite open-ended, isn't it?"},{"s":73.12,"e":78.46,"t":"Just research and analyze data about energy consumption in a given region."},{"s":78.86,"e":82.7,"t":"Yes, and all we've done so far is check out a few likely websites."},{"s":83.26,"e":85.62,"t":"Shall we exchange ideas about those first?"},{"s":85.54,"e":86.84,"t":"Hmm, good idea."},{"s":87.16,"e":88.94,"t":"Let me look at my notes."},{"s":89.82,"e":94.14,"t":"Okay, I had a preliminary look at one or two websites."},{"s":94.86,"e":96.96,"t":"There was National Geographic."},{"s":97.26,"e":102.78,"t":"The thing there that struck me was a facility for creating tailor-made maps."},{"s":103.26,"e":106.66,"t":"We might like to use that when it comes to presenting our findings."},{"s":107.98,"e":111.3,"t":"That would make some types of data instantly clear, I guess."},{"s":111.36,"e":114.84,"t":"Also, I checked out the United Nations website."},{"s":115.12,"e":119.4,"t":"That one had masses of useful stuff, only I couldn't get at it."},{"s":120.62,"e":122.64,"t":"It was for subscribers only, right?"},{"s":122.88,"e":125.22,"t":"And we don't want to get into that sort of thing."},{"s":125.44,"e":128.42,"t":"After all, it's not a major piece of work we're doing."},{"s":129.7,"e":134.8,"t":"I looked at the website of an agency called the Energy Information Administration."},{"s":146.64,"e":152.5,"t":"I thought the British Petroleum website might be a good place to get information about energy use."},{"s":152.5,"e":153.92,"t":"Oh, good thinking."},{"s":153.9,"e":156.32,"t":"There was lots of data, actually."},{"s":167.2,"e":170.46,"t":"So I didn't think it was quite what we were looking for."},{"s":170.66,"e":174.04,"t":"I also looked on the Central Intelligence Agency website."},{"s":173.96,"e":175.88,"t":"I never had thought of that."},{"s":177.56,"e":181.72,"t":"It seemed to be the only place I looked at that had data for this current year."},{"s":182.74,"e":185.58,"t":"I'm not sure about the websites I looked at."},{"s":185.4,"e":187.86,"t":"I didn't look carefully enough, I guess."},{"s":233.77,"e":235.37,"t":"We know roughly what we're doing."},{"s":235.67,"e":239.41,"t":"But have you got any more definite thoughts about what our subject matter should be?"},{"s":239.11,"e":245.39,"t":"I think one thing we've got to be careful about is biting off more than we can chew."},{"s":245.89,"e":250.03,"t":"Yes, especially as it doesn't count towards our final assessment anyway."},{"s":250.33,"e":255.85,"t":"So, shall we just limit it to data about population size and energy consumption?"},{"s":256.01,"e":260.03,"t":"How about if we add in one other factor, carbon emissions?"},{"s":260.67,"e":265.79,"t":"I think it'd be interesting to see what the interaction between those three factors is like."},{"s":267.07,"e":272.95,"t":"But in that case, we originally planned to stick to countries in North and South America."},{"s":273.49,"e":275.53,"t":"But what if we narrowed it down further?"},{"s":275.57,"e":277.15,"t":"I'd be happy with that."},{"s":277.67,"e":285.17,"t":"How about, let's say, 20 countries in all, the top 10 consumers of energy in the region, and also the bottom 10?"},{"s":286.69,"e":293.07,"t":"And we can calculate per capita consumption and per capita emissions to allow valid comparisons."},{"s":293.55,"e":299.57,"t":"Actually, it would be interesting to look at a breakdown of the types of energy each of those countries uses."},{"s":299.85,"e":305.03,"t":"You know, how much coal, how much wind power, how much nuclear power, and so on."},{"s":304.89,"e":307.75,"t":"But we did just agree to restrict our data."},{"s":309.19,"e":312.33,"t":"And then, what about the way we present our data?"},{"s":312.63,"e":318.19,"t":"Our tutor said that's one of the things she'll be looking at in particular, especially our graphics."},{"s":317.89,"e":322.79,"t":"Don't you think a bar chart would be more effective than a set of tables with figures?"},{"s":322.91,"e":325.65,"t":"It might, but I've got another idea."},{"s":325.93,"e":328.83,"t":"I'm keen to display our data on a map instead."},{"s":329.11,"e":332.17,"t":"We can easily find a software program to do that."},{"s":334.13,"e":337.13,"t":"One last thing, Charlie, and then we better go away and get started."},{"s":348.07,"e":351.03,"t":"But can you get them to me as soon as possible?"},{"s":353.45,"e":358.03,"t":"And I tell you what, since the graphics were my idea, I'll take those on."},{"s":358.27,"e":360.33,"t":"But do you mind doing the text?"},{"s":360.53,"e":362.81,"t":"You've got a better way with words than I have."}],"4":[{"s":77.02,"e":83.76,"t":"Before this morning's lecture on successful design of public buildings, I want to draw your attention to your next assignment."},{"s":94.54,"e":98.04,"t":"The assignment should be divided into three sections."},{"s":105.6,"e":108.44,"t":"Include a comment on whether you think the monument works."},{"s":108.56,"e":110.76,"t":"By that, I mean its success."},{"s":112.98,"e":116.56,"t":"You may think it's a public eyesore, something that people hate looking at."},{"s":133.0,"e":142.12,"t":"You should also include information on when it was built, its historical background, and make sure you illustrate the assignment appropriately, too."},{"s":177.33,"e":183.11,"t":"Firstly, I'll want to read about any particular influence you think is apparent in the design."},{"s":182.81,"e":188.97,"t":"More often than not, there will be something in it that links it to an established style."},{"s":189.11,"e":190.89,"t":"Classical Greek, for example."},{"s":191.55,"e":196.07,"t":"Or it may reflect a movement, like Bauhaus or Art Nouveau."},{"s":198.05,"e":202.05,"t":"Secondly, I want information about the choice of materials."},{"s":212.81,"e":218.53,"t":"Next, I'll want to mention of any particular skills that were necessary in the construction, too."},{"s":223.33,"e":226.03,"t":"Here, you'll go into much more critical detail."},{"s":234.81,"e":237.61,"t":"Ask yourself and others the following questions."},{"s":238.01,"e":241.67,"t":"Firstly, was the reason for erecting the monument a valid one?"},{"s":252.19,"e":256.25,"t":"Was it a waste, or does it represent a sound cultural investment?"},{"s":258.19,"e":260.85,"t":"Then, think about its emotional impact."},{"s":261.25,"e":263.75,"t":"When someone looks at it, how do they feel?"},{"s":267.13,"e":271.65,"t":"And don't forget to consider how well the monument sits in its environment."},{"s":272.05,"e":275.83,"t":"Does it harmonize with it, or does it clash with it?"},{"s":277.23,"e":280.55,"t":"Does it add to the effect or take away from it?"},{"s":280.93,"e":283.53,"t":"Right, those guidelines should help."},{"s":293.63,"e":297.43,"t":"You don't get extra marks for lots of factual information."},{"s":297.55,"e":300.75,"t":"You get those for a well-constructed analysis."}]},"3":{"1":[{"s":86.97,"e":90.49,"t":"You will see that there is an example that has been done for you."},{"s":100.84,"e":102.3,"t":"Good time restaurant."},{"s":106.06,"e":107.58,"t":"This is Brian Troy."},{"s":107.82,"e":111.82,"t":"We spoke last week about planning a party to celebrate my wife's promotion."},{"s":121.05,"e":124.55,"t":"The reason for the event is his wife's promotion."},{"s":125.35,"e":128.49,"t":"So, promotion has been written in the space."},{"s":129.73,"e":131.13,"t":"Now we shall begin."},{"s":152.22,"e":153.78,"t":"This is Brian Troy."},{"s":154.04,"e":158.04,"t":"We spoke last week about planning a party to celebrate my wife's promotion."},{"s":158.32,"e":164.36,"t":"Well, I would like to go ahead with it, and I have a list of things that I would like to go through with you."},{"s":164.06,"e":166.48,"t":"Yes, I remember."},{"s":174.42,"e":175.98,"t":"Have you decided yet?"},{"s":176.64,"e":181.66,"t":"Well, I think I would like to surprise my wife with a huge party."},{"s":182.02,"e":189.12,"t":"In fact, I've already started to contact a few of our friends and family, as well as some of the people my wife works with."},{"s":190.28,"e":193.14,"t":"So, let's get the party details confirmed."},{"s":194.06,"e":196.52,"t":"So, how many guests would you like?"},{"s":196.78,"e":198.86,"t":"Are you thinking of over a hundred?"},{"s":199.12,"e":206.82,"t":"No, I was thinking of more like fifty, but then I realized that we have friends that are living out of town."},{"s":207.32,"e":210.44,"t":"So, let's say eighty, in case everyone wants to come."},{"s":212.1,"e":214.7,"t":"And do you still want October 6th?"},{"s":217.38,"e":221.18,"t":"My daughter can't make it then, because she has a piano recital."},{"s":227.5,"e":229.88,"t":"Now, do you realize that's not a Saturday?"},{"s":230.3,"e":231.62,"t":"Are you okay with that?"},{"s":233.36,"e":237.6,"t":"When I look at my schedule, Friday is a better choice for all of us."},{"s":239.0,"e":241.66,"t":"Now we need to decide on the times."},{"s":245.66,"e":249.08,"t":"So, now let's talk about the room."},{"s":249.96,"e":252.46,"t":"I have several options that might work."},{"s":253.02,"e":258.26,"t":"There's the Queen Room, the Royal Room, the Palace Room, and the..."},{"s":257.96,"e":259.8,"t":"The King Room, right?"},{"s":260.06,"e":261.58,"t":"I've been there before."},{"s":261.56,"e":268.3,"t":"Actually, we recently renovated that room, and I think that it would be great for your party."},{"s":268.76,"e":270.74,"t":"You'll be very happy with it."},{"s":270.44,"e":272.16,"t":"Shall I book it for you?"},{"s":274.36,"e":277.34,"t":"Have you planned on having music while you're eating?"},{"s":282.44,"e":284.06,"t":"Well, you have some choices."},{"s":284.58,"e":289.52,"t":"We can arrange for a group to play jazz, or one to play the latest pop."},{"s":289.78,"e":297.12,"t":"I suspect my kids would prefer to have the pop music, but my wife is a jazz fan, so let's book that."},{"s":298.24,"e":300.08,"t":"I'll book that today."},{"s":300.78,"e":303.54,"t":"They're very good, and they might even sing at your table."},{"s":353.19,"e":357.77,"t":"Now we need to talk about the type of service you want for the dinner."},{"s":358.31,"e":359.85,"t":"We have two options."},{"s":359.55,"e":362.87,"t":"A self-service buffet or table."},{"s":363.49,"e":365.61,"t":"Let's go with the last choice."},{"s":365.91,"e":371.47,"t":"Just so you know, the price is the same for either chicken or a vegetarian plate."},{"s":371.93,"e":373.89,"t":"One last thing to decide on."},{"s":373.91,"e":376.67,"t":"Are you planning anything special for your wife?"},{"s":376.97,"e":383.91,"t":"Well, I was thinking that at eight o'clock or so, I would like to have a cake brought out."},{"s":391.29,"e":393.13,"t":"What flavor would you like?"},{"s":393.35,"e":396.15,"t":"Well, it would have to be lemon."},{"s":396.51,"e":401.57,"t":"I really love chocolate, but it is her day, so let's go with her favorite."},{"s":403.47,"e":405.79,"t":"Now, let me tell you about the cakes."},{"s":406.41,"e":413.93,"t":"We have a square cake, which would easily serve all of your guests, or you could have two cheesecakes."},{"s":414.31,"e":415.89,"t":"They're really popular right now."},{"s":416.21,"e":421.55,"t":"I prefer the first option, because I would like to have something special written on it."},{"s":423.65,"e":425.43,"t":"How about congratulations?"},{"s":427.19,"e":429.33,"t":"I can have our baker take care of that."},{"s":429.79,"e":432.61,"t":"He's happy to show you what it would look like if you wish."},{"s":433.19,"e":434.77,"t":"Now, is there anything else?"},{"s":435.75,"e":437.77,"t":"No, I don't think so."},{"s":437.47,"e":440.99,"t":"I think that we have pretty well talked about everything."},{"s":441.61,"e":444.01,"t":"So let's look after the reservation detail."},{"s":444.69,"e":447.05,"t":"I'll need to have a deposit of $50."},{"s":469.57,"e":474.51,"t":"Is there another name on the card beside Brian Troy?"},{"s":474.21,"e":476.53,"t":"A middle name or initial?"},{"s":478.49,"e":481.87,"t":"I will spell it for you."},{"s":489.21,"e":491.11,"t":"Is there anything else?"},{"s":491.07,"e":493.07,"t":"No, I think that's it."},{"s":493.59,"e":496.99,"t":"However, you need to be aware of an additional fee."},{"s":497.59,"e":504.47,"t":"For large groups, there is an extra charge which covers service, but I think that that's all for now."},{"s":504.85,"e":507.73,"t":"We look forward to having your celebration dinner here."}],"2":[{"s":44.51,"e":52.99,"t":"This week our slot is A Life in the Day of Joan Gilbert, local organiser for Riding for the Disabled."},{"s":53.41,"e":56.71,"t":"Joan, would you like to tell us about this?"},{"s":57.19,"e":65.21,"t":"Well, I always have the very best intentions of starting the day at 5.30 to give the horses a really good muck out."},{"s":65.67,"e":70.13,"t":"But reality intervenes and I finally wake at about 6.30."},{"s":120.25,"e":124.05,"t":"After cooking, I finally get round to the poor horses."},{"s":125.11,"e":134.17,"t":"It's only after this that I can start thinking about what I regard as my most important task – work for Riding for the Disabled."},{"s":135.33,"e":143.89,"t":"I've been involved with this organisation, on and off, for over 20 years, but I've only recently taken on the job of chairperson."},{"s":145.19,"e":150.01,"t":"Most of the work seems more secretarial, but that's how charities get organised."},{"s":150.97,"e":157.59,"t":"In our immediate district, we have had as many as 30 riders, but currently we've only got 22."},{"s":158.33,"e":167.01,"t":"The number of helpers who have volunteered is actually 40, but we can rely on 25 to come regularly to help in the different groups."},{"s":167.47,"e":174.69,"t":"We now have four separate groups which cater for disabled children and adults from 6 to 40 years old."},{"s":222.5,"e":231.26,"t":"As I say, I feel that although I no longer have any proper full-time paid employment, I do have a full and busy life."},{"s":231.78,"e":237.74,"t":"I'm a housewife, which I don't mind because I don't really object to doing things like washing and cooking."},{"s":238.46,"e":244.04,"t":"Then there's my own horses, which I adore – even the revolting stuff like cleaning out the stables."},{"s":245.22,"e":248.76,"t":"The official RDA stuff is a mixed bag, really."},{"s":249.14,"e":258.1,"t":"I don't have major problems with all the letter-writing and correspondence which it entails, but like lots of shy people, I find the fundraising horrendous."},{"s":268.56,"e":273.36,"t":"After all, that's why I'm involved with charity work – the contact with people."},{"s":274.08,"e":279.8,"t":"My working day ends with the least enjoyable job of all – sorting the accounts."},{"s":281.36,"e":289.3,"t":"I got involved with RDA because I've always loved horses and I can see disabled people gaining so much."},{"s":289.9,"e":296.92,"t":"I know all the medical evidence that shows that it does wonders for muscle building and so on, which is important."},{"s":310.71,"e":318.82,"t":"In terms of the RDA organisation itself, I feel it works very well, but we're always striving to make it better."},{"s":319.34,"e":330.84,"t":"I wish, for example, our helpers and the organisers in the various centres could really rationalise the fundraising efforts, which sometimes are very inefficient."},{"s":330.54,"e":338.24,"t":"And it also saddens me how unaware some of the stables can be about the difficulties faced by people who are disabled."},{"s":339.28,"e":345.72,"t":"Anyway, I feel very privileged to work with our riders and to see such tangible benefits."},{"s":347.44,"e":351.4,"t":"It sends me to sleep with a feeling that though the day has been hard, it has been worthwhile."}],"3":[{"s":51.37,"e":52.89,"t":"Did you have a good weekend?"},{"s":54.29,"e":58.01,"t":"It was good to relax after a whole week of teaching practice."},{"s":58.39,"e":60.63,"t":"I really enjoyed the experience though."},{"s":60.67,"e":62.45,"t":"Yes, so did I."},{"s":62.71,"e":64.27,"t":"And I think it went well."},{"s":64.73,"e":71.43,"t":"Anyway, are you okay to talk about the report we've got to write on the geography lesson we taught together?"},{"s":78.95,"e":81.51,"t":"Let's begin with our lesson aims, shall we?"},{"s":104.77,"e":106.87,"t":"We should include that information too."},{"s":118.81,"e":120.57,"t":"That wasn't in the core syllabus."},{"s":120.65,"e":122.45,"t":"I think we added that ourselves."},{"s":122.81,"e":124.63,"t":"Yes, I think you're right."},{"s":130.41,"e":135.39,"t":"We have to mention any problems we identified in our lesson when we taught it."},{"s":135.67,"e":136.97,"t":"So, any ideas?"},{"s":137.11,"e":142.09,"t":"Well, I know we were really satisfied with our handouts and worksheets."},{"s":142.35,"e":145.89,"t":"We both thought they'd been at just the right level for the class."},{"s":146.33,"e":150.59,"t":"And I don't know about you, but I think we worked well as a team."},{"s":152.11,"e":155.49,"t":"Neither of us was too dominant and we supported each other."},{"s":155.77,"e":160.69,"t":"Personally, the thing I think we didn't get right was the way we paced things."},{"s":161.21,"e":165.27,"t":"Some things seemed to be rushed and others seemed to drag out too long."},{"s":165.69,"e":167.55,"t":"I don't know how you feel about that."},{"s":167.61,"e":169.03,"t":"The same as you."},{"s":169.45,"e":176.21,"t":"If we did the same lesson again, I'd want to make some adjustments to that, but keep the same basic lesson plan."},{"s":194.51,"e":196.61,"t":"Yes, I remember that too."},{"s":196.69,"e":199.19,"t":"And we should put it into our report as well."},{"s":243.93,"e":251.02,"t":"Now, should we go over our lesson plan together before we write the report?"},{"s":251.22,"e":252.9,"t":"It seems ages ago now."},{"s":254.06,"e":259.88,"t":"Well, the whole lesson was based on the production and distribution of pencils."},{"s":259.82,"e":264.94,"t":"First, we gave out the pencils and got the students to decide what they're made of."},{"s":265.44,"e":272.9,"t":"Then when they'd come up with all five of the component materials, we talked about which countries produce most of these materials."},{"s":274.26,"e":279.88,"t":"And we got volunteers to come to the front and mark the location of those on a map of the world."},{"s":280.16,"e":282.72,"t":"I remember they were really keen to volunteer."},{"s":282.94,"e":285.74,"t":"We had to stop them from calling the answers out loud."},{"s":297.62,"e":300.58,"t":"I remember one girl talking about using horses."},{"s":302.06,"e":304.32,"t":"She seemed to be a bit stuck in the past."},{"s":304.76,"e":306.26,"t":"It was hard not to smile."},{"s":307.48,"e":314.36,"t":"After that, we put them in small groups, and each group represented each of the countries on the map."},{"s":326.26,"e":328.7,"t":"And by the time they'd done that, it was break time."},{"s":352.02,"e":362.0,"t":"And to round the lesson off, the kids had to spend ten minutes planning a short presentation for another class about possible developments."},{"s":362.44,"e":363.86,"t":"And that was it."},{"s":364.86,"e":366.4,"t":"So I'll write up that part."}],"4":[{"s":81.26,"e":89.32,"t":"Today I'm going to talk about what is sometimes described as the world's oldest mechanical computer, the Antikythera Mechanism."},{"s":89.02,"e":98.06,"t":"This device was able to calculate where the sun, moon and planets would be in the sky on any date in the past or future."},{"s":98.52,"e":105.2,"t":"It has transformed our understanding both of the world of ancient Greece and of the history of science."},{"s":115.48,"e":121.96,"t":"It was in the cargo of a ship that sank about 2,100 years ago."},{"s":122.62,"e":128.5,"t":"Divers brought various items to the surface and they were taken to a museum for examination."},{"s":129.46,"e":132.18,"t":"One item was assumed to be a lump of rock."},{"s":145.98,"e":154.44,"t":"Further investigation revealed that it was in fact some sort of mechanism and they decided to call it the Antikythera Mechanism."},{"s":155.46,"e":161.72,"t":"Although it was badly damaged, it had survived in three main parts and around 80 smaller fragments."},{"s":174.22,"e":183.32,"t":"One machine, called a dome, can surround a sample and take photographs with the light coming from slightly different angles."},{"s":184.32,"e":190.46,"t":"This has made far more of the inscriptions on the mechanism legible, even though they're faded and worn."},{"s":191.44,"e":200.26,"t":"Another state-of-the-art machine, the Blade Runner, has been used to take x-rays which show parts of the mechanism that would otherwise be invisible."},{"s":220.2,"e":229.12,"t":"It seems the device was originally about 33 centimetres high, 17 centimetres wide and 9 centimetres thick."},{"s":247.86,"e":256.86,"t":"These gear wheels, in turn, operated small movable models of the Sun, Moon and the five planets that were known to the ancient Greeks."},{"s":256.56,"e":262.56,"t":"The mechanism is thought to have been mounted in a frame for which wood was used."},{"s":268.06,"e":270.98,"t":"So what was the Antikythera Mechanism used for?"},{"s":271.24,"e":274.28,"t":"It clearly had an astronomical function."},{"s":302.6,"e":308.88,"t":"Perhaps most astonishing of all, the mechanism also showed when an eclipse was going to take place."},{"s":309.54,"e":317.54,"t":"This was very important in the ancient world and being able to predict this accurately would have given the user great power."},{"s":318.2,"e":328.52,"t":"The mechanism probably also helped in planning the timing of festivals, both agricultural and religious, by acting as a kind of calendar of events."},{"s":329.84,"e":338.38,"t":"Surprisingly, to the best of our knowledge, no device equalled the complexity of the Antikythera Mechanism for at least a thousand years afterwards."},{"s":338.86,"e":346.14,"t":"The ideas seem to have survived in some form, however, particularly in the Byzantine Empire of the Eastern Mediterranean."},{"s":361.2,"e":368.0,"t":"It's hard to believe that nothing reached the sophistication of the Antikythera Mechanism for a thousand years."},{"s":368.42,"e":375.5,"t":"Yet that might well be the case and that has implications for our understanding of how scientific knowledge progresses."}]},"4":{"1":[{"s":91.1,"e":95.18,"t":"You will see that there is an example that has been done for you."},{"s":103.95,"e":107.77,"t":"Hello, Superior Home Appliances, this is Ian here."},{"s":107.93,"e":109.37,"t":"Oh, hello, yes."},{"s":109.63,"e":113.19,"t":"I have a new fridge and I'm ringing to report a fault with it."},{"s":112.89,"e":116.19,"t":"I need you to send someone out to have a look at it."},{"s":119.26,"e":124.32,"t":"The type of appliance is a fridge, so fridge has been written in the space."},{"s":125.52,"e":127.1,"t":"Now we shall begin."},{"s":143.0,"e":146.96,"t":"Hello, Superior Home Appliances, this is Ian here."},{"s":147.08,"e":148.6,"t":"Oh, hello, yes."},{"s":148.62,"e":152.24,"t":"I have a new fridge and I'm ringing to report a fault with it."},{"s":152.42,"e":154.96,"t":"I need you to send someone out to have a look at it."},{"s":156.0,"e":162.3,"t":"I'll fill in a customer complaint form and arrange for one of our repair agents to come out to you."},{"s":163.7,"e":167.62,"t":"Now, can I just get some contact details from you for the form?"},{"s":167.32,"e":168.98,"t":"Your name is?"},{"s":172.76,"e":175.94,"t":"And if I can just get a contact telephone number?"},{"s":184.42,"e":187.6,"t":"Now, can I get some more details about the fridge?"},{"s":188.12,"e":191.46,"t":"Well, it's been playing up since yesterday afternoon."},{"s":193.08,"e":194.8,"t":"And is it still under warranty?"},{"s":195.18,"e":197.3,"t":"Well, I should think so."},{"s":197.54,"e":199.46,"t":"It's only a couple of weeks old."},{"s":199.42,"e":200.9,"t":"That's fine then."},{"s":201.08,"e":205.78,"t":"Now, I just need to get some more information about the make and model."},{"s":206.2,"e":209.74,"t":"Is it a top mount, a bottom mount or a side-by-side?"},{"s":210.24,"e":211.7,"t":"The freezer is on top."},{"s":212.32,"e":214.58,"t":"And have you got the model number there?"},{"s":215.96,"e":218.72,"t":"It's here on the instructions booklet."},{"s":225.88,"e":227.34,"t":"So it's silver in colour."},{"s":228.98,"e":232.34,"t":"I thought it was so much nicer than the usual white ones."},{"s":233.02,"e":236.32,"t":"Now, if I could just get a few details from you."},{"s":236.5,"e":239.16,"t":"First, when did you buy the fridge?"},{"s":239.44,"e":245.98,"t":"Well, as I said, it was only a few weeks ago, but I don't have the receipt in front of me at the moment."},{"s":245.68,"e":250.32,"t":"I do know that it was delivered on the 6th of February."},{"s":251.52,"e":254.76,"t":"Well, I can use that date to search on the computer."},{"s":259.28,"e":263.14,"t":"It says here you bought it on January the 12th."},{"s":263.16,"e":265.74,"t":"Now, what exactly is wrong with the fridge?"},{"s":265.9,"e":271.24,"t":"Well, my fridge is fitted with an alarm and it started to go off."},{"s":270.94,"e":273.42,"t":"It made an awful noise."},{"s":273.62,"e":274.94,"t":"So what was wrong?"},{"s":275.3,"e":279.62,"t":"Well, when I went to check the freezer, it felt pretty warm."},{"s":279.9,"e":284.94,"t":"It's 10 degrees and it should be minus 18, so everything is melting."},{"s":285.36,"e":289.24,"t":"And then the main part of the fridge doesn't seem to be working either."},{"s":289.18,"e":290.54,"t":"Mmm, I see."},{"s":334.98,"e":339.4,"t":"I've made a note of that on the form and I'll pass it on to the service agent."},{"s":339.72,"e":341.54,"t":"When can they come and fix it?"},{"s":341.7,"e":344.32,"t":"Let's find the closest one to you."},{"s":346.92,"e":355.18,"t":"That's Ken's Appliances and they've got two centres in your area, one near the station and another one in the shopping centre."},{"s":355.42,"e":361.28,"t":"Well, we're miles away from the shopping centre, so the station one would be closer."},{"s":361.6,"e":367.2,"t":"I'll ring them in a minute, but I should warn you it could take a day or two for them to get to you."},{"s":368.7,"e":371.14,"t":"What am I going to do without a fridge?"},{"s":371.72,"e":375.68,"t":"Look, there's a fridge full of food there and it's all going off."},{"s":375.94,"e":378.36,"t":"I'll have to throw it all out, you know."},{"s":378.06,"e":380.5,"t":"Yes, I do sympathise."},{"s":381.22,"e":382.64,"t":"It's not just that."},{"s":382.98,"e":384.84,"t":"This is going to affect my business."},{"s":385.02,"e":388.7,"t":"I run a sandwich shop and that's where I keep my stock."},{"s":399.8,"e":407.14,"t":"Well, I've just filled it with $180 worth of meat and salad, so that would be something, I suppose."},{"s":407.86,"e":411.72,"t":"But how long is my business expected to survive without a fridge?"},{"s":412.04,"e":413.5,"t":"It's just not good enough."},{"s":414.0,"e":419.1,"t":"Yes, I understand your concerns, but that's all I can really offer you."},{"s":419.42,"e":423.08,"t":"Well, I'd like to speak to someone higher up about this."},{"s":423.66,"e":427.74,"t":"I can ask my manager to ring you back by close of business today."},{"s":429.38,"e":430.74,"t":"Yes, thank you."},{"s":430.72,"e":433.24,"t":"I do apologise for all the inconvenience."},{"s":437.04,"e":439.1,"t":"Actually, there is one more thing."},{"s":439.3,"e":442.7,"t":"The door has a dent in it on the left-hand side."},{"s":443.02,"e":446.54,"t":"It wasn't there in the shop, so it must have happened when it was delivered."},{"s":446.84,"e":448.7,"t":"I'd like that replaced too."},{"s":448.86,"e":450.58,"t":"I'll make a note of that too."},{"s":450.9,"e":452.94,"t":"You'll be hearing from us very soon."}],"2":[{"s":61.61,"e":69.39,"t":"Listeners to this programme will know that we're very keen to foster links within communities, and we think we've hit on a winning idea."},{"s":119.13,"e":125.51,"t":"In the course of their studies or work in this country, some people rarely get the opportunity to socialise."},{"s":125.93,"e":134.97,"t":"There may be language problems or feelings of shyness, which mean that whatever their age, people can become quite lonely or isolated."},{"s":170.01,"e":174.49,"t":"So, what will you, the guest, get out of a visit?"},{"s":189.97,"e":200.33,"t":"It's early days, but if a weekend stay goes well, relationships might develop over time and turn into lasting and genuine friendships."},{"s":210.67,"e":218.81,"t":"There's also the possibility that when you return to your own country, you might one day want to invite your hosts to stay with you."},{"s":267.16,"e":273.34,"t":"Right, I hope I've given you enough information on the scheme and what we're setting out to do."},{"s":273.94,"e":279.8,"t":"I'll now deal with the process for applying, if you'd like to be involved from the point of view of a guest."},{"s":280.2,"e":284.6,"t":"So have a pencil and some paper ready to jot down what you need to do."},{"s":285.66,"e":293.42,"t":"Connections is broken up into various small sections which will deal with your application through the different stages."},{"s":294.02,"e":298.5,"t":"To begin with, we ask you to make a phone call to our vetting people."},{"s":299.04,"e":304.76,"t":"We need to know some basic information about you, like how long you're intending to be in this country."},{"s":304.92,"e":307.5,"t":"The minimum time limit is three months."},{"s":308.02,"e":318.12,"t":"Whether you're working or studying, we require a reference, which must be from the person in authority who you're working with or studying under."},{"s":318.62,"e":321.44,"t":"This will be used for an identity check."},{"s":322.42,"e":329.78,"t":"Once that's been sent to the authorities and approved, we'll email you an application form which you can download."},{"s":330.66,"e":336.58,"t":"You should complete this and return it with two recent passport-sized photographs of yourself."},{"s":337.46,"e":346.34,"t":"One photo will be held in our records and the other will be sent to your host family prior to your first weekend visit."},{"s":361.46,"e":369.24,"t":"At that point, you should have some idea of weekend dates when you're free, which we can put to the host family."},{"s":369.7,"e":377.06,"t":"However, decisions are not made at the meeting, but you can expect to hear the result from us in a couple of days."},{"s":377.7,"e":381.42,"t":"Now, the process for those of you interested in welcoming..."}],"3":[{"s":64.79,"e":72.68,"t":"Have you had a chance to look at the information for our project yet, Beth?"},{"s":83.08,"e":84.52,"t":"Yeah, me too."},{"s":84.9,"e":89.58,"t":"The main message is that seasonal allergies seem to be getting worse."},{"s":123.76,"e":131.4,"t":"But it was only in Britain that cod liver oil was so popular so that argument doesn't really make sense."},{"s":131.2,"e":133.74,"t":"No, it doesn't seem that relevant."},{"s":134.4,"e":142.0,"t":"What seems to be happening now is that an increasing number of people are getting their first attack in their 40s and 50s."},{"s":141.86,"e":147.18,"t":"That must be because of the link with climate change causing rising temperatures."},{"s":147.78,"e":151.84,"t":"But CO2 levels are seriously affecting pollen counts too."},{"s":167.08,"e":171.38,"t":"So people might experience more severe allergic symptoms in future?"},{"s":172.48,"e":176.24,"t":"And another factor is that the pollen season is changing."},{"s":182.96,"e":184.94,"t":"That's in the long term."},{"s":185.4,"e":188.82,"t":"But that doesn't mean that spring will come earlier every year."},{"s":189.1,"e":190.64,"t":"Look at last winter."},{"s":190.92,"e":195.7,"t":"That was really cold until March and the pollen season was delayed."},{"s":196.24,"e":200.02,"t":"Whereas this year spring came earlier and lasted longer."},{"s":201.0,"e":203.98,"t":"And another thing we should mention is ragweed."},{"s":204.0,"e":210.6,"t":"As an example of a plant species moving into new areas as a result of climate change."},{"s":211.74,"e":218.32,"t":"In the US it's already the major allergen affecting millions of people in August and September."},{"s":218.78,"e":225.64,"t":"But we're starting to see it grow in Europe for the first time, which is really worrying because it's so allergenic."},{"s":238.18,"e":241.98,"t":"Wasn't the pollen shown to be three times higher in one city?"},{"s":243.74,"e":249.34,"t":"So because of this, many cities have started to ban the planting of certain types of trees."},{"s":292.31,"e":299.03,"t":"So shall we look at the different data tables for seasonal changes for pollen in Europe?"},{"s":305.13,"e":310.23,"t":"So that's oak trees and birch trees and grass."},{"s":310.33,"e":312.59,"t":"Yes, that makes it more manageable."},{"s":312.87,"e":318.85,"t":"Shall we go through the data for each country in detail and pick out anything interesting?"},{"s":320.09,"e":323.27,"t":"So starting with Austria."},{"s":323.83,"e":327.41,"t":"Well, here we've only got data for birch pollen."},{"s":327.85,"e":330.63,"t":"I wonder why there's no data for oak or grass?"},{"s":331.35,"e":335.27,"t":"It would be interesting to compare with neighbouring countries."},{"s":336.47,"e":338.67,"t":"The picture in France is unusual."},{"s":339.61,"e":346.43,"t":"The pollen season starts earlier for both oak and birch, but it doesn't start any earlier for grass."},{"s":346.81,"e":348.21,"t":"I wonder why that is?"},{"s":352.97,"e":356.05,"t":"So what does it show?"},{"s":356.57,"e":364.95,"t":"Grass and birch pollen are only starting a few days earlier, but oak pollen is starting much earlier."},{"s":366.75,"e":368.53,"t":"Hmm, that's unusual."},{"s":368.83,"e":371.77,"t":"There's not such a big difference in other countries."},{"s":373.27,"e":374.93,"t":"Switzerland's an interesting case."},{"s":375.21,"e":380.67,"t":"The pollen season starts here earlier than in the past for oak, birch and grass."},{"s":380.37,"e":385.17,"t":"Yeah, from 21 days to 14 days earlier."},{"s":385.95,"e":388.59,"t":"The UK shows a different picture again."}],"4":[{"s":131.16,"e":133.6,"t":"No wonder the spice is so expensive!"},{"s":149.74,"e":154.24,"t":"This makes it possible to keep saffron on the shelf to be used for many years."},{"s":154.92,"e":162.98,"t":"The highly prized spice is famous for the flavor and aroma it imparts, which are often compared to that of honey."},{"s":203.4,"e":209.36,"t":"It is found to varying degrees in Italian, Spanish, Indian, and Iranian food."},{"s":223.6,"e":230.34,"t":"Patients given saffron in their regular diet seem to show remarkable signs of recovery from serious conditions."},{"s":246.72,"e":254.08,"t":"Now, I'd like to give a few examples of how saffron has been used since ancient times."},{"s":272.74,"e":277.0,"t":"This is the earliest evidence of saffron being used as a dye."},{"s":277.66,"e":286.78,"t":"During the Roman Empire, saffron oil was produced, which, because of both its color and aroma, was used to create cosmetics."},{"s":287.62,"e":290.66,"t":"But only the wealthiest citizens could afford these."},{"s":291.86,"e":295.66,"t":"Another use of saffron was to be found in the public baths."},{"s":296.3,"e":301.84,"t":"There, saffron was used as a perfume to keep the places smelling fresh and aromatic."},{"s":317.28,"e":320.26,"t":"Other parts of the ancient world used saffron extensively."},{"s":320.8,"e":331.56,"t":"One of the most well-known examples was in Persia, which is modern-day Iran, where saffron was a vital part of the process of manufacturing carpets."}]},"5":{"1":[{"s":79.52,"e":83.34,"t":"You will see that there is an example that has been done for you."},{"s":92.38,"e":94.3,"t":"Good morning, library services."},{"s":94.34,"e":95.72,"t":"Oh, good morning."},{"s":96.1,"e":101.68,"t":"My family and I have recently moved to the area and we'd like to find where our nearest library is."},{"s":103.06,"e":105.8,"t":"Right, so whereabouts are you?"},{"s":105.72,"e":107.58,"t":"In Perton, in the west."},{"s":107.7,"e":111.28,"t":"Fine, so I'll just get the details on screen for you."},{"s":113.64,"e":121.48,"t":"The woman is asking about libraries in the west of the area, so west has been written in the space."},{"s":122.92,"e":124.44,"t":"Now we shall begin."},{"s":140.0,"e":142.02,"t":"Good morning, library services."},{"s":141.72,"e":143.54,"t":"Oh, good morning."},{"s":143.92,"e":149.52,"t":"My family and I have recently moved to the area and we'd like to find where our nearest library is."},{"s":149.5,"e":150.82,"t":"We don't have a car."},{"s":151.1,"e":153.58,"t":"Right, so whereabouts are you?"},{"s":153.62,"e":155.4,"t":"In Perton, in the west."},{"s":155.46,"e":159.28,"t":"Fine, so I'll just get the details on screen for you."},{"s":167.06,"e":168.94,"t":"Can you spell that?"},{"s":169.26,"e":177.8,"t":"It's S-K-E-L-L-A-R-N Street."},{"s":179.0,"e":181.74,"t":"It's very easy to find because it's beside a park."},{"s":181.94,"e":183.86,"t":"Oh, I think I know that area."},{"s":184.16,"e":186.5,"t":"There's a sports centre near there, isn't there?"},{"s":186.56,"e":188.1,"t":"I don't know of one."},{"s":188.16,"e":190.36,"t":"Oh, I'm probably mistaken."},{"s":190.06,"e":194.34,"t":"Anyway, it's probably a bit far for us to walk from home."},{"s":195.7,"e":198.2,"t":"Yes, it's well-served by public transport."},{"s":198.62,"e":200.94,"t":"There's a stop about five minutes' walk away."},{"s":202.48,"e":205.0,"t":"And when does the library open?"},{"s":205.36,"e":207.84,"t":"We'll most often want to come at the weekend."},{"s":208.12,"e":210.42,"t":"I'm afraid it's not open on Sunday."},{"s":212.06,"e":215.2,"t":"Opens at 9 o'clock, closes at 4.30."},{"s":215.54,"e":217.6,"t":"We shut at 5 on weekdays."},{"s":219.02,"e":225.84,"t":"Now, I've got two kids, 14 and 9, and I wondered whether you have any special activities for them."},{"s":226.0,"e":228.4,"t":"In our last place, we had an art club."},{"s":228.46,"e":234.46,"t":"Well, the library does run a drama club, but that would only be suitable for your younger child."},{"s":234.78,"e":237.12,"t":"It's open for 5 to 13-year-olds."},{"s":236.82,"e":239.66,"t":"A pity it's not open to both of them."},{"s":240.08,"e":242.34,"t":"Have you anything they could both go to?"},{"s":242.5,"e":245.5,"t":"Well, there's no reading club that would suit them both."},{"s":246.06,"e":252.6,"t":"Oh, but there's a singing club that's held every second Saturday afternoon for children of all ages up to 16."},{"s":297.12,"e":302.92,"t":"Now, because we're new to the area, I'm also wanting to get involved in local activities."},{"s":303.28,"e":306.28,"t":"Well, Minack does some sessions for adults as well."},{"s":306.56,"e":308.14,"t":"There's a book of the month club."},{"s":309.2,"e":316.88,"t":"And I know that about once every 12 months, they have a session where you can meet artists, you know, from the local area."},{"s":321.5,"e":325.82,"t":"Now, while I'm on the phone, can I check what the facilities are?"},{"s":326.02,"e":327.72,"t":"Can you take out CDs?"},{"s":328.02,"e":330.9,"t":"Not CDs, I'm afraid, but films, yes."},{"s":331.6,"e":332.96,"t":"I'll make a note of that."},{"s":333.1,"e":334.66,"t":"Anything else you need to know?"},{"s":335.44,"e":343.16,"t":"We have 10 computers and we also stock several magazines, including business, healthcare and hobbies."},{"s":343.36,"e":344.84,"t":"Same as my last place."},{"s":345.26,"e":351.24,"t":"And there is a new drop-off facility where you can post any item through the door if it's after hours."},{"s":351.48,"e":355.76,"t":"All you have to do is attach a note to it with the number on your card clearly written."},{"s":356.92,"e":361.58,"t":"And we do have a small shop on the premises where we sell postcards."},{"s":361.28,"e":364.26,"t":"We don't have many, but it's a popular service."},{"s":364.12,"e":366.0,"t":"Oh, that's a good idea."},{"s":367.5,"e":371.66,"t":"We also have an impressive range of maps of the surrounding area for sale."},{"s":372.0,"e":374.04,"t":"Well, it sounds like you've got..."}],"2":[{"s":54.64,"e":60.02,"t":"And welcome to this orientation session prior to our camp next week."},{"s":60.5,"e":66.08,"t":"Thank you for coming along to find out what you and your children will be doing on this year's camp."},{"s":86.14,"e":92.3,"t":"Now, if you cross the road from the car park, the first building you'll come to is the toilet block."},{"s":92.0,"e":98.48,"t":"It's been recently upgraded, so it's very nice and clean in there now with plenty of facilities."},{"s":99.46,"e":105.38,"t":"And built onto that, so this is across the road from the community hall, is the new shower block."},{"s":106.16,"e":112.26,"t":"The hot water does run out occasionally, but usually there's enough to cope with a group your size."},{"s":126.18,"e":129.74,"t":"Now, let's go back and move along the top of your map."},{"s":130.18,"e":137.74,"t":"There's another area of pine forest, and then over on the far right-hand side, there's a block of small cabins."},{"s":138.6,"e":146.78,"t":"Note that this is different from the main accommodation block, which doesn't appear on this map, but is further over again to the right."},{"s":154.8,"e":162.06,"t":"In this next block, beside the flower beds, we have a lovely place for barbecues, where you can cook in the open air."},{"s":163.26,"e":165.04,"t":"What else to tell you about?"},{"s":166.24,"e":174.78,"t":"Below the flower bed and across Lakeside Drive, you'll see a trail for mountain biking, which is always a popular activity."},{"s":181.96,"e":185.74,"t":"And above that again, the community hall."},{"s":186.84,"e":189.68,"t":"So that completes your introduction to the campsite."},{"s":189.92,"e":191.5,"t":"I hope you found that useful."},{"s":229.43,"e":233.01,"t":"Now let's think about what you need to bring with you."},{"s":233.31,"e":236.15,"t":"I'm sure you're all wondering what you need to pack."},{"s":236.91,"e":243.03,"t":"The lake is a bit cold for swimming at this time of year, so you can leave your togs out of the suitcase."},{"s":243.67,"e":250.03,"t":"While we're on the subject of weather too, usually I recommend that campers bring sunblock with them."},{"s":249.73,"e":253.99,"t":"But I guess now that we're into April, that too can be left behind."},{"s":266.81,"e":274.71,"t":"So I'd say that a pair of earplugs are more useful, as in my experience, a lot of talking goes on after light's out."},{"s":274.95,"e":281.45,"t":"But in April, if it's wet, it can get muddy around the campsite, so to bring boots isn't a bad idea."},{"s":282.41,"e":287.31,"t":"Finally, can you all please prepare something for the final night concert?"},{"s":291.53,"e":294.07,"t":"You can't have a camp without a good sing-along."},{"s":294.27,"e":295.77,"t":"That's our favourite activity."},{"s":296.57,"e":302.95,"t":"Maybe you could recite a poem, act out a skit or charades for us if you're brave enough to try that."},{"s":303.21,"e":306.83,"t":"Or failing that, perhaps you can tell a joke or a funny story."},{"s":307.59,"e":310.91,"t":"But actually, people much prefer to see some good dancing."},{"s":311.53,"e":314.17,"t":"I'll look forward to seeing you all perform next week."}],"3":[{"s":52.78,"e":59.34,"t":"So Gareth, we need to organise the findings from our survey on music students for the final presentation."},{"s":59.36,"e":63.08,"t":"Yes Lorna, I think we've got some very interesting results."},{"s":75.22,"e":80.1,"t":"And then we should talk about the students' musical backgrounds before coming to university."},{"s":79.8,"e":88.86,"t":"The most important points to make are that although most people have actually composed music during the course, that wasn't the case when they arrived."},{"s":89.44,"e":92.04,"t":"And the other thing they had in common was the piano."},{"s":92.14,"e":97.76,"t":"Well, they'd had access to a piano at some point, but not all had studied it formally."},{"s":109.8,"e":112.36,"t":"But varying enormously in size."},{"s":112.88,"e":115.04,"t":"Some had only played in tiny venues."},{"s":115.38,"e":117.06,"t":"I think it's worth saying that."},{"s":118.12,"e":125.86,"t":"And as you might expect from people wanting to study music, they all had a degree of proficiency in at least two instruments."},{"s":126.16,"e":129.28,"t":"But in most cases, one of the instruments was dominant."},{"s":130.56,"e":134.18,"t":"We need to talk about attitudes to music practice."},{"s":149.04,"e":151.84,"t":"It's interesting what was said about practising alone."},{"s":152.2,"e":156.2,"t":"Some people preferred that because they could focus more on their weak points."},{"s":156.3,"e":158.54,"t":"But that wasn't a majority view."},{"s":158.94,"e":165.08,"t":"What most of them agree on is that there's nothing more rewarding than mastering something that's really hard to learn."},{"s":167.16,"e":172.64,"t":"After that, we should talk a bit about the pieces that students select for assessed performances."},{"s":172.82,"e":176.04,"t":"There wasn't quite so much consensus on this, was there?"},{"s":175.82,"e":184.14,"t":"A few people prefer to do pieces which are relatively unknown, while others choose the ones they think will show off their technical ability."},{"s":184.54,"e":186.18,"t":"But they were in the minority."},{"s":199.26,"e":208.18,"t":"And quite a lot of them said it helps to listen to other people playing your chosen piece, preferably recordings, but even just other students."},{"s":245.99,"e":251.75,"t":"So finally, we need to look at the findings for students' attitudes to performing."},{"s":252.19,"e":259.05,"t":"We should point out that this includes informal and formal public performances as well as assessed ones."},{"s":258.93,"e":260.65,"t":"Yes, that's important."},{"s":261.41,"e":267.69,"t":"I expected to find that performing solo would make students very nervous, but in fact that isn't the case."},{"s":267.83,"e":273.79,"t":"They do find it hugely challenging to start with, but they appreciate the challenge and find it stimulating."},{"s":275.43,"e":279.59,"t":"I was surprised by what students said about deciding which pieces to perform."},{"s":280.11,"e":281.89,"t":"I thought they'd all say this was easy."},{"s":282.03,"e":284.39,"t":"For me, it's always been quite straightforward."},{"s":284.67,"e":288.67,"t":"Which pieces do I like best and which pieces can I play well?"},{"s":288.93,"e":291.47,"t":"And my repertoire is quite limited anyway."},{"s":291.63,"e":296.05,"t":"But the most commonly cited answer was that it took them ages to make their minds up."},{"s":295.89,"e":299.19,"t":"I suppose it's because there are so many factors involved."},{"s":307.73,"e":311.83,"t":"You need to think about all these things and you can't do that in a hurry."},{"s":313.33,"e":319.73,"t":"Then there's performing with musicians from a different genre, like a classical musician playing with a jazz group."},{"s":319.83,"e":321.23,"t":"That can really be fun."},{"s":321.21,"e":324.99,"t":"But most of the music students had never even considered it."},{"s":326.05,"e":331.49,"t":"For performing with musicians who play the same instrument, almost everyone put the same thing."},{"s":338.89,"e":340.57,"t":"Yes, that's a good point."}],"4":[{"s":105.01,"e":110.91,"t":"It was, of course, only in the 19th century that engineering really emerged as a profession."},{"s":111.39,"e":120.73,"t":"Initially, ethical issues were considered to be a personal matter, something to be decided in accordance with one's own principles and values."},{"s":138.77,"e":144.69,"t":"Unfortunately, it took three major disasters to bring about this change in attitude."},{"s":145.31,"e":148.99,"t":"All three of these involved the collapse of bridges."},{"s":161.87,"e":166.45,"t":"Then in 1879 there was a second disaster, this time in Scotland."},{"s":166.89,"e":174.03,"t":"This occurred because engineers had failed to correctly calculate the effects that wind would have on the structure."},{"s":174.69,"e":178.47,"t":"The third collapse occurred in 1907 in Canada."},{"s":178.85,"e":182.35,"t":"This was also due to an engineering design problem."},{"s":182.53,"e":188.41,"t":"The weight of the structure was so great that it could not support itself, and it collapsed."},{"s":188.97,"e":199.53,"t":"Public outcry over disasters such as these eventually led to the establishment of professional societies for engineers in most industrializing societies."},{"s":211.75,"e":219.55,"t":"This incident, which happened early in the twentieth century, is known as the Boston Molasses Disaster."},{"s":220.51,"e":226.35,"t":"At the time, molasses was used rather than sugar as the principal sweetener in the USA."},{"s":226.91,"e":231.73,"t":"It was also used in the manufacture of a number of other important products."},{"s":232.57,"e":239.79,"t":"One company in the city of Boston had a large amount of molasses waiting to be transferred to another factory."},{"s":240.11,"e":247.85,"t":"The molasses, more than eight million liters of thick, sticky liquid, was stored in a tank."},{"s":248.51,"e":254.07,"t":"Suddenly this collapsed, unleashing a wave of molasses up to five meters high."},{"s":254.33,"e":258.91,"t":"Nearby buildings were swept off their foundations and crashed to the ground."},{"s":259.59,"e":263.77,"t":"The wave also swept away a considerable stretch of railway track."},{"s":264.13,"e":270.09,"t":"Many streets round the factory were covered with a thick layer of sticky brown molasses."},{"s":274.77,"e":279.67,"t":"Local residents were furious, as they felt that the company was to blame."},{"s":299.59,"e":305.77,"t":"Even today, no one is absolutely sure about the immediate causes of the accident."},{"s":306.25,"e":310.83,"t":"However, it is certainly clear that not enough safety tests were carried out."},{"s":311.11,"e":318.65,"t":"Had these been done in accordance with the standards now applicable, then the accident would almost certainly have been prevented."},{"s":319.09,"e":328.27,"t":"It seems that the collapse was probably brought about by fermentation of the molasses, which led to an increase in pressure."},{"s":328.77,"e":335.83,"t":"This increase probably exerted too much force against a fatigue crack or some other weakness."},{"s":335.53,"e":347.41,"t":"However, this was one of the main incidents which led to increased legislation in the 1920s to regulate engineers and the engineering profession."},{"s":348.05,"e":354.11,"t":"It is the reason why we can now only operate if we have gained a license."},{"s":354.81,"e":362.23,"t":"This requires us always to be conscientious about doing everything necessary to avoid disasters."},{"s":361.93,"e":367.99,"t":"However time-consuming or expensive this may sometimes seem."}]},"6":{"1":[{"s":58.62,"e":61.88,"t":"London Relocation Services, Daniel speaking."},{"s":64.56,"e":69.34,"t":"My family and I are moving to London later this year and I wonder if you can help?"},{"s":70.06,"e":73.38,"t":"First of all, I'll need to get some personal details."},{"s":73.58,"e":75.8,"t":"May I take your full name, please?"},{"s":75.82,"e":77.42,"t":"It's Anna Woods."},{"s":80.4,"e":83.66,"t":"Northern Ireland, just outside Belfast, actually."},{"s":84.52,"e":86.72,"t":"And what's your current address?"},{"s":90.3,"e":91.9,"t":"I'll spell that for you."},{"s":99.72,"e":101.36,"t":"And what's the postcode?"},{"s":107.04,"e":109.74,"t":"And could I take a contact phone number?"},{"s":123.18,"e":127.86,"t":"Now, we always like to get a bit more information about the families that we're moving."},{"s":128.06,"e":129.44,"t":"It helps with the search."},{"s":129.68,"e":131.22,"t":"Are you moving for work?"},{"s":131.48,"e":134.3,"t":"Yes, my husband's just got a new job in London."},{"s":134.38,"e":135.74,"t":"And what about you?"},{"s":136.66,"e":144.48,"t":"Well, I've been working as a teaching assistant recently, but I'm actually a qualified nurse and I'd like to get back into that if possible."},{"s":145.44,"e":147.6,"t":"And do you have any children?"},{"s":148.96,"e":150.92,"t":"So we need to find a school for him."},{"s":150.62,"e":153.46,"t":"Is it a secondary school you'll be looking for?"},{"s":153.44,"e":155.64,"t":"No, he's still in primary school."},{"s":155.88,"e":158.18,"t":"He's not quite at the secondary level yet."},{"s":159.4,"e":163.0,"t":"So let's go on to talk about your requirements for the property."},{"s":163.2,"e":165.08,"t":"Do you have a preferred location?"},{"s":165.18,"e":167.16,"t":"Is your husband's job in the centre?"},{"s":167.62,"e":171.8,"t":"No, it's in East London, but we'd rather live somewhere quieter."},{"s":181.04,"e":187.36,"t":"So I imagine that ideally he'd like to be not too far from a station then?"},{"s":187.36,"e":193.06,"t":"Yes, he drives now, but I guess that's not going to be possible and he's not keen on buses."},{"s":193.3,"e":195.08,"t":"What about you or your son?"},{"s":194.9,"e":196.26,"t":"Do you have any preferences?"},{"s":196.52,"e":199.06,"t":"Does your son do any sport, for example?"},{"s":199.38,"e":203.88,"t":"He's quite active, so I'm sure he'd love a park nearby to run around in."},{"s":204.06,"e":206.52,"t":"He doesn't do swimming or anything like that."},{"s":238.72,"e":241.46,"t":"So what sort of property do you have in mind?"},{"s":241.8,"e":249.16,"t":"We have friends who live in an amazing flat over there, but as we've always lived in a house, I think we'll stick with that."},{"s":249.26,"e":251.38,"t":"We'd find it hard to adapt to a flat."},{"s":252.72,"e":255.82,"t":"And size-wise, how many bedrooms would you like?"},{"s":256.06,"e":259.22,"t":"Well, there's just myself, my husband and our son."},{"s":259.42,"e":262.74,"t":"So you'd definitely need a two-bedroom property."},{"s":263.08,"e":264.86,"t":"But how about having a guest room?"},{"s":264.88,"e":267.84,"t":"I might be able to find a three-bedroom property for you."},{"s":267.9,"e":269.44,"t":"Yes, that would be ideal."},{"s":269.54,"e":271.76,"t":"We're sure to have family visiting often."},{"s":272.04,"e":274.12,"t":"All right, I've made a note of that."},{"s":274.52,"e":277.52,"t":"Now are there any other requirements for your new property?"},{"s":278.0,"e":284.8,"t":"Well, it's not essential, but it'd be handy to have an office for when my husband works from home."},{"s":285.02,"e":286.7,"t":"It doesn't need to be a big one."},{"s":286.98,"e":288.74,"t":"I guess it all comes down to budget."},{"s":291.22,"e":294.02,"t":"Well, I've certainly got enough to be getting on with and..."}],"2":[{"s":87.63,"e":90.15,"t":"Welcome to Holly's Supermarket."},{"s":90.55,"e":94.69,"t":"I'm sure you'll all enjoy working in our dedicated team here."},{"s":95.31,"e":97.23,"t":"So, what will you be doing?"},{"s":97.31,"e":105.71,"t":"Well, we're open Monday through Sunday, so you'll need to be able to work weekends as well as irregular weekday shifts."},{"s":120.75,"e":125.21,"t":"But you'll only be required to do manual lifting if the goods are light."},{"s":126.87,"e":132.41,"t":"When the store is very busy, you'll also have to assess changing priorities."},{"s":132.87,"e":138.01,"t":"For example, if there's a queue at the tills, you'll jump on a spare one to help."},{"s":138.47,"e":144.91,"t":"If you notice something's been spilt and the surface is a little bit wet, you'll get a mop to clean it up."},{"s":145.05,"e":147.63,"t":"No need to check with a manager first."},{"s":148.67,"e":153.25,"t":"Similarly, if bakery items are selling quickly, you'll help cook some more."},{"s":153.55,"e":160.83,"t":"And if a customer can't find, say, the apples, you'll instantly leave what you're doing and show them."},{"s":160.89,"e":164.79,"t":"But you'll still get time off to relax too, of course."},{"s":165.33,"e":169.17,"t":"We pride ourselves on a positive attitude here."},{"s":179.87,"e":181.81,"t":"And always smile."},{"s":181.95,"e":188.05,"t":"It forces you to stay positive and being generally upbeat makes your whole team happy too."},{"s":188.58,"e":192.65,"t":"This increases efficiency and gives a good impression to customers."},{"s":193.37,"e":196.33,"t":"If it's quiet, help someone pack their bags."},{"s":196.53,"e":201.63,"t":"Customers really appreciate it, especially when they've bought more than they expected to."},{"s":226.87,"e":231.39,"t":"You have to make sure, however hard it might be, that you remain composed."},{"s":277.05,"e":280.59,"t":"So, now let's look at the plan of the supermarket."},{"s":280.99,"e":282.91,"t":"Have you all got your plans?"},{"s":285.27,"e":287.71,"t":"We'll start with the staff entrance."},{"s":298.09,"e":305.03,"t":"Please don't confuse this with the emergency exits in the top right-hand corner and bottom left."},{"s":305.53,"e":309.31,"t":"It's very important that these are kept clear at all times."},{"s":311.56,"e":319.74,"t":"Regarding the manager's office, some of you may have attended interviews here, when it was next to the newspaper and magazine sales area."},{"s":320.14,"e":326.92,"t":"However, it's recently been moved and is now the circular space marked on the right of your plans."},{"s":326.62,"e":331.1,"t":"When the manager's not on the shop floor, that's where you'll find her."},{"s":332.42,"e":334.94,"t":"The storage and unpacking area."},{"s":335.12,"e":339.86,"t":"You may be asked to help out here, both before and after opening hours."},{"s":345.86,"e":352.26,"t":"It tends to get very busy there at times, so please be careful on entering and leaving this area."},{"s":352.8,"e":357.62,"t":"There's a kitchen on site, where food and drinks are prepared for customers."},{"s":358.0,"e":362.56,"t":"It has specialist staff, but some of you may have to fill in occasionally."},{"s":369.24,"e":376.56,"t":"It's very busy, as many customers like to take a break in the cafe and read a newspaper, before or after doing their shopping."},{"s":377.52,"e":380.24,"t":"Cleaning equipment is stored in a cupboard."},{"s":386.56,"e":391.84,"t":"You'd be surprised how often we have to mop up squashed tomatoes or grapes."},{"s":393.14,"e":397.04,"t":"Finally, you'll be pleased to know there's a separate staff relaxation area."},{"s":402.62,"e":409.16,"t":"As well as comfortable chairs, there's also a microwave for heating up snacks and a drinks dispenser."},{"s":408.86,"e":411.62,"t":"So, let's go there now."}],"3":[{"s":47.18,"e":53.42,"t":"Hi, are you ready to discuss our presentation?"},{"s":54.72,"e":59.22,"t":"So, what are we going to say about teachers reading picture books with young children?"},{"s":60.44,"e":63.78,"t":"I think we should start with the reasons why teachers use picture books."},{"s":63.86,"e":69.1,"t":"The journal article we read mentioned several picture books, and why they're popular with teachers."},{"s":70.02,"e":71.7,"t":"Like, I spy friends."},{"s":71.5,"e":72.88,"t":"It's a lovely story."},{"s":73.3,"e":78.54,"t":"The children like to find the familiar faces from the fairy tales they know so well."},{"s":78.88,"e":80.58,"t":"And they're all doing predictable things."},{"s":80.94,"e":84.2,"t":"The article said children find this familiarity very comforting."},{"s":85.62,"e":90.72,"t":"Now, how about Goodnight Little Rabbit, which has those delightful pictures?"},{"s":91.24,"e":97.28,"t":"I love the way the colours get darker as the book progresses, indicating how evening turns into night."},{"s":98.28,"e":100.72,"t":"The article said that's why teachers like it."},{"s":102.12,"e":104.48,"t":"And a good example of visual subtext."},{"s":104.54,"e":107.94,"t":"Hard to believe that it came out over 60 years ago."},{"s":109.7,"e":112.48,"t":"I really liked what the article said about the boat party."},{"s":112.94,"e":116.78,"t":"There's a lot of repetition, which I think would be great for vocabulary development."},{"s":118.32,"e":121.94,"t":"But apparently it's the images that make it popular with children."},{"s":122.38,"e":126.1,"t":"The artist is really well known, and children often ask for her books."},{"s":128.72,"e":131.5,"t":"And shall we also include Puppy and Friends?"},{"s":141.6,"e":144.8,"t":"Teachers like to use this to help children explore their emotions."},{"s":146.32,"e":148.38,"t":"Hats and Socks is a good one."},{"s":148.74,"e":151.84,"t":"It doesn't really have a beginning and an end, does it?"},{"s":151.74,"e":153.06,"t":"Which is unusual."},{"s":161.86,"e":164.48,"t":"And the pages are so full of life and colour."},{"s":167.58,"e":171.4,"t":"And for our last one, how about A Family Adventure?"},{"s":172.24,"e":178.46,"t":"This one uses a lot of the same language throughout, which I think can help with letter and word recognition."},{"s":179.0,"e":181.88,"t":"Teachers say it has a really poetic feel to it."},{"s":182.04,"e":184.28,"t":"They often sing it to a simple tune."},{"s":223.84,"e":228.28,"t":"In the next part of our presentation, shall we look at some of the other research?"},{"s":228.92,"e":232.36,"t":"I really liked Smith's article about the history of picture books."},{"s":235.26,"e":240.0,"t":"And as we know from our reading lists, there's a lot of research on them already."},{"s":240.8,"e":242.48,"t":"Smith makes some interesting points."},{"s":242.78,"e":249.48,"t":"Yes, one thing that shocked me was that some people don't consider picture books as proper writing because they don't have enough words in them."},{"s":249.94,"e":252.36,"t":"Yes, that was unexpected for me as well."},{"s":252.84,"e":256.2,"t":"I think they should be just as respected as other works of fiction."},{"s":266.08,"e":268.26,"t":"But it's the same for adult fiction too."},{"s":268.46,"e":269.88,"t":"People want variety."},{"s":270.58,"e":273.82,"t":"What I didn't realise is how fixed the number of pages is."},{"s":275.28,"e":279.26,"t":"I wasn't expecting that they're so strictly limited to 32 pages."},{"s":279.78,"e":282.04,"t":"It's important, so let's include it."},{"s":283.22,"e":287.56,"t":"Now let's think about other aspects of picture books we want to include in our presentation."},{"s":288.24,"e":289.56,"t":"How about the characters?"},{"s":289.86,"e":296.12,"t":"Okay, well, a lot of them feature animals, or families often in very traditional roles."},{"s":296.66,"e":298.84,"t":"But do you think we need to talk about that?"},{"s":299.36,"e":303.44,"t":"For me, the main thing is that they are mostly printed as board books."},{"s":303.82,"e":307.66,"t":"The cardboard material makes it easy for young children to turn their pages."},{"s":309.0,"e":315.64,"t":"And it's essential for children to hold books and learn how they open at the front, and that the text goes in a certain direction."},{"s":317.32,"e":323.74,"t":"Why don't we also discuss how culture is important in picture books, like the importance of respecting the elderly?"},{"s":324.18,"e":327.02,"t":"Yes, it's probably different all over the world."},{"s":327.92,"e":334.9,"t":"Would it be interesting to make a comparison between modern and historical picture books and consider future directions for the genre?"},{"s":335.32,"e":340.46,"t":"It sounds interesting, but I don't have any research on that, so we'd better leave it."}],"4":[{"s":75.65,"e":81.27,"t":"Next week is the Geography 331 field trip to the far north of Quebec."},{"s":81.67,"e":85.45,"t":"Today I'll discuss your trip and your tasks."},{"s":86.15,"e":89.67,"t":"As you know, you will be close to the Arctic Circle."},{"s":90.03,"e":98.45,"t":"You're going to travel up the James Bay Road through a region that is very remote and uninhabited, yet very beautiful."},{"s":98.49,"e":106.07,"t":"The highway is 620 km long, but it's fully paved for the entire length."},{"s":107.35,"e":112.93,"t":"Where the highway begins, there is a roadside office where you must stop."},{"s":113.31,"e":119.17,"t":"The road is remote, so your registration is very important in case of an emergency."},{"s":119.93,"e":125.05,"t":"The office is staffed 24 hours per day, 7 days per week."},{"s":125.45,"e":130.47,"t":"You have to sign in to go up the road and sign out upon your return."},{"s":130.17,"e":140.47,"t":"For additional safety, at different places along the highway, telephones have been installed which connect with staff in the office."},{"s":141.39,"e":145.27,"t":"Remember, there is no mobile service in this remote area."},{"s":146.23,"e":155.63,"t":"The first work of your field trip is at the end of the James Bay Road in Radisson, a small town of only 300 inhabitants."},{"s":155.33,"e":167.27,"t":"You will stay at Radisson Research Centre, which works with various universities and Hydro-Québec to carry out studies into the ecology of the region."},{"s":199.25,"e":203.61,"t":"After that, you will visit the various outpost stations."},{"s":233.68,"e":239.36,"t":"In fact, it's very uneven gravel, so drivers have to be very careful."},{"s":239.8,"e":247.22,"t":"Hydro-Québec cautions that driving over rocks on the rough road may cause severe damage to the car."},{"s":246.92,"e":251.68,"t":"Any breakdown is serious, as repairs are costly."},{"s":252.86,"e":259.64,"t":"Along the way, you will be stopping at two hydroelectric generating stations, each on a different river."},{"s":259.92,"e":268.68,"t":"There, you will meet with engineers who will explain and demonstrate how rainfall has an impact on producing electric energy."},{"s":269.12,"e":275.8,"t":"Your last two days of the trip will be spent camping out in the taiga on the Canadian Shield."},{"s":302.18,"e":308.9,"t":"These low-lying areas are called muskeg, which is made up of slowly decomposing plants."},{"s":309.54,"e":317.02,"t":"It is not safe to walk on it, as it has pools that are not easily seen, so keep to the rocks."},{"s":317.78,"e":321.6,"t":"The muskeg is home to many small birds and waterfowl."},{"s":321.92,"e":330.92,"t":"In fact, there are at least 60 varieties, so keep your waterproof digital cameras handy so you can take plenty of pictures."},{"s":331.68,"e":338.12,"t":"Then we will have documentation of the existing waterfowl, as some are becoming extinct."},{"s":339.2,"e":348.06,"t":"Water is a problem in this area, so you'll also be collecting test tubes of water to bring back to our research lab for analysis."},{"s":348.66,"e":354.28,"t":"It needs to be monitored for pollution that may be caused by rainfall coming from the south."}]},"7":{"1":[{"s":102.82,"e":107.68,"t":"Yes, I'm looking for some places to visit when my sister and her children come to stay."},{"s":108.12,"e":110.1,"t":"They arrive this weekend from overseas."},{"s":110.78,"e":113.58,"t":"I'm new to the area and don't really know what to recommend."},{"s":113.86,"e":115.18,"t":"Do you have any ideas?"},{"s":115.34,"e":118.64,"t":"What about going to Alma Park to visit the zoo?"},{"s":118.34,"e":120.74,"t":"Oh, I like the idea of that."},{"s":121.14,"e":122.78,"t":"Is it reasonably priced?"},{"s":122.98,"e":124.84,"t":"Yes, it's not a bad price."},{"s":125.18,"e":133.24,"t":"A standard adult ticket is normally $30, but there's a special deal for families of $65, which is a saving of $35."},{"s":133.6,"e":135.06,"t":"That's a great deal."},{"s":135.32,"e":137.18,"t":"How do we get there from the city?"},{"s":139.78,"e":144.92,"t":"The 385 will get you there in approximately 40 minutes, depending on traffic."},{"s":144.62,"e":152.82,"t":"There is another bus, the 388, but it takes 20 minutes longer, so it's worth waiting a few more minutes for the more direct bus."},{"s":154.58,"e":156.84,"t":"Are there any special things to do there?"},{"s":156.98,"e":159.36,"t":"Can you feed the animals or anything like that?"},{"s":159.4,"e":166.32,"t":"They've stopped that, but most tourists love the fact that you're allowed to hold some of the animals and get your photo taken."},{"s":166.74,"e":170.04,"t":"They just ask you to make a small payment to help with costs."},{"s":169.74,"e":171.98,"t":"Oh, the kids would love that."},{"s":172.14,"e":174.6,"t":"My sister also likes going to the theatre."},{"s":175.0,"e":176.74,"t":"Is there anything good on at the moment?"},{"s":177.0,"e":178.9,"t":"She especially likes comedies."},{"s":179.24,"e":182.42,"t":"There's a place called the Entertainment Room in Ascot."},{"s":182.7,"e":184.22,"t":"I'll just check their website."},{"s":191.24,"e":193.22,"t":"How do you spell that?"},{"s":193.24,"e":195.12,"t":"Is it R-O-Z-Y?"},{"s":195.12,"e":197.78,"t":"No, it's R-O-S-I-E."},{"s":201.6,"e":206.96,"t":"It says it starts on Tuesday with a special matinee show on the Wednesday."},{"s":207.3,"e":212.3,"t":"It was supposed to finish on Friday, but because of the demand it's been extended to Saturday."},{"s":213.76,"e":215.28,"t":"Is it expensive?"},{"s":224.46,"e":226.28,"t":"We'll try and go then in that case."},{"s":265.13,"e":267.53,"t":"The children will get bored just looking at the shops."},{"s":267.85,"e":269.75,"t":"Is there anything else for them to do?"},{"s":269.45,"e":271.59,"t":"What's the museum like?"},{"s":271.53,"e":276.83,"t":"It's very popular with children, and there's a very hands-on exhibition on at the moment."},{"s":279.17,"e":282.41,"t":"And there's a workshop on, where they learn how to do origami."},{"s":282.89,"e":285.27,"t":"Will they need to bring anything special for that?"},{"s":285.39,"e":290.39,"t":"On this leaflet it says that things like scissors and all of the paper are provided."},{"s":290.09,"e":295.03,"t":"They just advise children to bring a box to carry the completed origami home in."},{"s":297.07,"e":299.53,"t":"I'm also looking for a weekend activity."},{"s":299.93,"e":301.97,"t":"I've heard Bunyabi Island is great."},{"s":302.03,"e":304.23,"t":"Would we need a car to get round the island?"},{"s":304.37,"e":307.01,"t":"A four-wheel drive is a great way to explore."},{"s":307.89,"e":310.33,"t":"You should also try snorkelling at Salty Lake."},{"s":310.81,"e":313.25,"t":"Is that in the centre of the island, near the mountain?"},{"s":313.27,"e":315.25,"t":"No, it's on the ocean side."},{"s":325.95,"e":328.35,"t":"That would be lovely, but I'm afraid..."}],"2":[{"s":35.38,"e":43.3,"t":"Good evening and thank you for coming to the Kenvale School Fair Volunteers Meeting."},{"s":57.58,"e":64.68,"t":"I'll begin tonight by talking about the different volunteer roles, so you can decide what you'd like to do."},{"s":87.9,"e":94.62,"t":"We need an advertising and promotion coordinator to make sure that people hear about the fair and lots of people come."},{"s":95.44,"e":101.34,"t":"We know this is a big job, so we've decided to have a couple of people doing it to share the load."},{"s":121.62,"e":131.0,"t":"Now, this may sound like a technical background is required, but it's not, as you don't actually have to set up or fix anything yourself."},{"s":141.52,"e":144.06,"t":"We also need a staffing coordinator."},{"s":144.64,"e":148.72,"t":"This person will be required to look after the many helpers on the day of the fair."},{"s":149.48,"e":154.22,"t":"This role has just been created based on our experience of last year's event."},{"s":154.82,"e":161.52,"t":"We found that our volunteers felt a bit overworked, and so we're hoping that this role will make things easier."},{"s":162.44,"e":167.08,"t":"It will help to reduce stress if you organise the helpers about a month before the fair."},{"s":222.85,"e":229.89,"t":"You can see that we'll be using the large grounds just behind the school, and we'll set up temporary areas and pathways there."},{"s":230.65,"e":235.81,"t":"The first thing I'll show you are the fairground rights, which are always popular with the children."},{"s":237.07,"e":240.21,"t":"If you look at the map, you'll see the fair entrance at the bottom."},{"s":248.99,"e":256.05,"t":"The entertainment stage is a big feature of the fair, and this is where everyone will be able to see all the performers."},{"s":256.79,"e":260.61,"t":"To find this, go straight along the main path until you get to the river."},{"s":261.59,"e":264.91,"t":"Turn right and follow the path to the end, and there it is."},{"s":271.41,"e":276.05,"t":"If anyone wants a cold drink or a snack, then they'll ask you where the cafe is."},{"s":285.57,"e":286.95,"t":"You can see it on the map."},{"s":287.37,"e":291.25,"t":"It's the circular area, surrounded by trees, near the playground."},{"s":293.25,"e":296.77,"t":"The first A tent is always an important part of the fair."},{"s":297.63,"e":305.45,"t":"We wanted to put that in an area that was easily accessible, and a bit separated from the other attractions, but near the entrance."},{"s":312.61,"e":317.91,"t":"The market stalls are where visitors will be able to pick up a bargain, or some homemade produce."},{"s":318.53,"e":325.91,"t":"Last year, these were located just south of the meeting area, but the stallholders complained that it was too exposed and hot."},{"s":326.35,"e":329.85,"t":"So, this year, we've moved them to the north of the meeting area."},{"s":330.37,"e":333.41,"t":"Lots of good shelter provided by the trees here."}],"3":[{"s":53.38,"e":54.92,"t":"Do you have time to talk?"},{"s":55.54,"e":61.8,"t":"We have to submit our evaluations of our course next week, and I thought it'd be useful to discuss what we both think."},{"s":63.24,"e":68.06,"t":"That would help refresh my memory, especially about things we did in previous years."},{"s":69.6,"e":71.9,"t":"So, let's talk about the modules we took."},{"s":72.6,"e":75.44,"t":"What about statistics for environmental research?"},{"s":76.02,"e":80.08,"t":"I've always been hopeless with numbers, so I thought that I'd learn a lot."},{"s":80.32,"e":83.74,"t":"But, you know, it wasn't at a high enough level for me."},{"s":84.04,"e":86.84,"t":"I actually had to do a lot of reading on my own."},{"s":87.92,"e":90.66,"t":"I had to get an additional reading list from the tutor."},{"s":90.36,"e":94.36,"t":"Now, sewage and drainage systems."},{"s":94.6,"e":97.02,"t":"I wasn't looking forward to that one."},{"s":97.08,"e":107.14,"t":"Not exactly a pleasant subject, but, you know, the module convinced me that it's an essential topic to understand for both cities and rural environments."},{"s":108.18,"e":111.54,"t":"And, in the end, not a boring subject."},{"s":112.82,"e":114.6,"t":"It was quite a revelation."},{"s":114.94,"e":119.26,"t":"The module on agriculture and food security could have been good."},{"s":118.96,"e":124.2,"t":"But the assigned readings were only those ancient government publications."},{"s":124.34,"e":128.46,"t":"And the lecture notes clearly hadn't been updated for years."},{"s":130.4,"e":133.26,"t":"What about the module on sustainable energy?"},{"s":133.76,"e":137.66,"t":"I really got into the project we had to do to invent something functional."},{"s":138.12,"e":140.7,"t":"I devised a windmill to power my laptop."},{"s":141.7,"e":143.4,"t":"The projects were great."},{"s":144.86,"e":149.12,"t":"Though the personal battery charger I built never really worked."},{"s":150.54,"e":152.58,"t":"But I'm sure you learned a lot nonetheless."},{"s":153.96,"e":155.68,"t":"And the government policy module?"},{"s":156.06,"e":159.24,"t":"I wish it had included policy in other countries."},{"s":159.54,"e":164.46,"t":"It was a bit inward-looking, I thought, focused just on this country."},{"s":164.58,"e":170.88,"t":"I mentioned that to the lecturer, but she said it was best to concentrate on one country in depth at first."},{"s":172.16,"e":174.84,"t":"And there was that module called Water Management."},{"s":175.32,"e":183.82,"t":"I must admit, I got lost in the discussion about the issues of groundwater levels and flood risk management, which weren't that essential."},{"s":184.0,"e":185.76,"t":"You weren't the only one."},{"s":228.48,"e":229.94,"t":"Can we talk a bit about that?"},{"s":231.92,"e":236.98,"t":"Actually, I was disappointed that I couldn't take any module whenever I wanted."},{"s":238.1,"e":244.14,"t":"But the variety of modules on offer was a strong point and meant I managed to cover a lot of subjects."},{"s":247.2,"e":256.46,"t":"I had wanted to finish the course early by doing an extra module each term, which would have been useful, but unfortunately that wasn't allowed."},{"s":256.86,"e":261.1,"t":"I had to wait to do some modules, which I found hard to schedule."},{"s":260.8,"e":267.62,"t":"And I think more assigned reading for the modules would have made the lectures easier to follow."},{"s":278.4,"e":281.94,"t":"And I would have hated it if it had all been theory."},{"s":282.2,"e":285.32,"t":"What about the written paper we had to do for Dr Brown?"},{"s":285.92,"e":289.22,"t":"Are there any things we could suggest to improve the way that's handled?"},{"s":289.88,"e":296.58,"t":"Well, I got lots of help from Dr Brown and his assistant in narrowing down what I wanted to write about."},{"s":296.54,"e":299.88,"t":"Yes, they stopped me from doing something too ambitious."},{"s":300.58,"e":304.32,"t":"But choosing a topic right at the beginning of the module was difficult."},{"s":304.86,"e":308.54,"t":"Maybe he could postpone the decision until halfway through the term."},{"s":309.82,"e":312.64,"t":"I was happy with the word limit for the assignment though."},{"s":312.34,"e":320.52,"t":"Well, as usual, I could have written on and on, but the limit made me refine my thoughts, so it was OK in the end."},{"s":320.64,"e":325.48,"t":"I wish I could have had a session with Dr Brown after he'd marked my written paper."},{"s":325.82,"e":330.52,"t":"I know it would be time-consuming, but it would have been really useful."},{"s":331.36,"e":335.02,"t":"Actually, I was satisfied with Dr Brown's written feedback."},{"s":335.38,"e":338.88,"t":"It was amazingly detailed, so I don't think I needed more."},{"s":338.58,"e":346.12,"t":"But I wish they could arrange sessions where students get together and help each other before submitting their written work."},{"s":347.56,"e":350.88,"t":"If they provided time for that, it would be quite convenient."},{"s":352.6,"e":357.46,"t":"Now that we've almost finished our course, it's time to think about our career prospects."},{"s":357.9,"e":360.66,"t":"What type of organisation do you hope to work for?"}],"4":[{"s":81.88,"e":87.44,"t":"He's considered one of the leading composers of modern classical music in Europe."},{"s":88.04,"e":97.1,"t":"His music is highly unusual, so in order to prepare you for this concert, I'm going to talk about his life and music."},{"s":98.24,"e":100.98,"t":"First, some biographical details."},{"s":101.78,"e":108.58,"t":"Salvatore Schiarino was born in the Italian city of Palermo in 1947."},{"s":109.48,"e":115.02,"t":"Though he did receive some music lessons, he is mainly self-taught as a composer."},{"s":115.96,"e":125.58,"t":"After a few years of university in his home city, he moved to Rome in 1969, where he studied electronic music."},{"s":126.26,"e":132.56,"t":"This experience served as a turning point in the development of Schiarino as a composer."},{"s":133.42,"e":143.04,"t":"Turning to his work, he composed a great deal in the 1970s and was a music teacher until 1982."},{"s":170.9,"e":176.3,"t":"So you could say that he is one of the most important composers of our times."},{"s":181.42,"e":188.34,"t":"Now I'll talk about the characteristics of his music, which some people are a bit surprised by."},{"s":188.04,"e":196.66,"t":"The first thing that many listeners will notice about Schiarino's music is the frequent use of silence."},{"s":231.96,"e":237.98,"t":"Actually, his novel instrumental techniques have often been imitated by other composers."},{"s":238.64,"e":245.68,"t":"As a result, he is widely regarded as a pioneer in terms of creating new sounds."},{"s":246.12,"e":255.32,"t":"It may sound strange, but Schiarino himself has likened his music to a volcano viewed from afar."},{"s":256.16,"e":261.54,"t":"As you'll see, it builds up slowly to an exciting climax."},{"s":262.54,"e":268.04,"t":"Let's move on to talk about the particular piece that we'll hear at the concert."},{"s":268.78,"e":272.8,"t":"Many people consider it to be his finest work to date."},{"s":273.28,"e":282.06,"t":"It's an immense piece of music for piano, chorus and orchestra that was completed in 1979."},{"s":283.44,"e":290.68,"t":"The work is dedicated to a friend who died unexpectedly, so it was written as a kind of memorial."},{"s":291.8,"e":298.56,"t":"In many ways, it is representative of his work as a whole in terms of the sound that it creates."},{"s":299.2,"e":305.06,"t":"It's technically formidable and it's a very challenging piece for musicians to play."},{"s":304.76,"e":312.92,"t":"The piece opens with a low sound of great complexity that is similar to thunder."},{"s":326.92,"e":337.2,"t":"The sound, by the way, is created by large vibrating sheets of metal, which are slowly manipulated by two percussionists."},{"s":337.72,"e":349.8,"t":"There are very quiet and strange chords produced by string instruments and very complex piano melodies that quietly appear and then disappear."},{"s":367.36,"e":369.7,"t":"Now let's move on to another work."}]},"8":{"1":[{"s":84.53,"e":87.95,"t":"You will see that there is an example that has been done for you."},{"s":126.19,"e":134.47,"t":"The caller wishes to arrange a weekend away for himself and some colleagues, so option C has been circled."},{"s":175.39,"e":177.41,"t":"What else would you like to know?"},{"s":177.95,"e":181.43,"t":"Well, firstly, what kind of accommodation have you got?"},{"s":181.53,"e":187.59,"t":"We've got eight rooms altogether and we can sleep 38 at any one time."},{"s":187.89,"e":192.67,"t":"Three of the rooms have got six bunks and five of them have got four bunks."},{"s":192.73,"e":196.17,"t":"Right, and what other facilities are there?"},{"s":196.15,"e":199.89,"t":"We have separate toilets and showers for each of the rooms."},{"s":214.73,"e":216.95,"t":"We've got workmen coming in next week."},{"s":217.47,"e":219.23,"t":"When were you thinking of staying?"},{"s":219.51,"e":222.65,"t":"In three weeks' time, the 28th of September."},{"s":222.35,"e":224.91,"t":"Oh, it should be OK by then."},{"s":224.99,"e":227.17,"t":"Oh, well, that's OK then."},{"s":227.05,"e":228.81,"t":"And what about food?"},{"s":228.99,"e":231.91,"t":"Do you provide meals or is it self-catering?"},{"s":231.97,"e":233.49,"t":"We're very flexible."},{"s":243.53,"e":246.89,"t":"And some people prefer to eat out, which is also fine."},{"s":248.55,"e":251.09,"t":"And I heard that your farm is organic."},{"s":251.43,"e":254.41,"t":"Does that mean that you only have crops and no animals?"},{"s":254.57,"e":256.41,"t":"It doesn't, actually."},{"s":256.55,"e":263.39,"t":"A lot of people seem to think that, but we do rear livestock as well, and so we have a wide range of food."},{"s":263.85,"e":269.51,"t":"Organic means it's all produced without the use of artificial fertilisers or pesticides."},{"s":273.07,"e":279.47,"t":"Could you tell me what sort of recreational activities are available, either at the centre or in the area?"},{"s":280.75,"e":283.63,"t":"Here at the centre, we offer farm tours."},{"s":283.61,"e":285.01,"t":"They're very popular."},{"s":285.35,"e":291.01,"t":"One of the farm managers shows people around and explains some of the principles of organic farming."},{"s":291.61,"e":299.71,"t":"And for any visitors who are really keen, you let them drive a tractor or feed the animals and so on, with supervision, of course."},{"s":299.41,"e":302.81,"t":"I think a lot of our group would be interested in that."},{"s":302.99,"e":305.33,"t":"It'd make a change from factory work."},{"s":305.45,"e":308.23,"t":"Well, if they fancy it, tell them to come prepared."},{"s":308.39,"e":311.63,"t":"Plenty of old clothing, especially footwear."},{"s":311.75,"e":314.11,"t":"It can be very messy and wet."},{"s":364.01,"e":372.71,"t":"And another type of activity we do is survival courses, but that's only for groups of five or more, and they've got to be acquaintances."},{"s":372.95,"e":374.71,"t":"They have to cooperate closely."},{"s":375.55,"e":381.37,"t":"These courses are very popular, especially with school groups, but adults seem to enjoy them too."},{"s":381.39,"e":383.09,"t":"What do they involve?"},{"s":383.05,"e":384.73,"t":"Things like map reading?"},{"s":384.43,"e":387.33,"t":"Well, not exactly."},{"s":387.47,"e":393.87,"t":"What it is, we've got a large area of woodland on the farm and we run this course there."},{"s":394.33,"e":401.85,"t":"It's mainly about collecting food and water, lighting a fire without any equipment, that kind of thing."},{"s":409.15,"e":412.77,"t":"If you look at a map, you'll see that we're very well situated here."},{"s":413.15,"e":422.61,"t":"Our centre's about midway between the Exmoor National Park, which is very popular for hill walking, and the south coast, which has very good beaches."},{"s":422.93,"e":424.99,"t":"Are they both within walking distance?"},{"s":437.07,"e":439.43,"t":"You can hire bikes at the starting point."},{"s":440.15,"e":442.43,"t":"What is there to do if the weather's bad?"},{"s":442.73,"e":444.83,"t":"I hope it won't be, but you never know."},{"s":446.41,"e":454.61,"t":"Well, on most Saturday evenings we show films here and then once a month a group of local musicians performs in our meeting room."},{"s":455.41,"e":458.57,"t":"And then Sherbourne is only 14 miles away."},{"s":464.57,"e":467.11,"t":"Well, it sounds perfect for our purposes."},{"s":467.91,"e":470.55,"t":"One last thing, what about prices?"},{"s":470.79,"e":475.17,"t":"I'm not sure yet, but there'll probably be about 15 of us."},{"s":488.45,"e":493.21,"t":"Use of the kitchen facilities is extra, as is the hire of the meeting room."},{"s":492.91,"e":497.77,"t":"It depends, really, what exactly you want and for how many people."},{"s":498.87,"e":502.81,"t":"Well, I've made a note of all that and I'll discuss it with the rest of the group."},{"s":503.17,"e":505.21,"t":"Then I'll get back to you with a firm booking."},{"s":506.75,"e":513.45,"t":"Yes, you can, but once you've made a booking we would need a deposit within five days to secure it."},{"s":513.53,"e":515.73,"t":"Then you just pay the balance when you're here."},{"s":515.43,"e":517.11,"t":"Oh, yes, of course."},{"s":517.85,"e":520.65,"t":"Could you give me the address, please?"},{"s":533.45,"e":539.65,"t":"And the postcode is S-H-12-1-L-Q."}],"2":[{"s":10.93,"e":17.41,"t":"It describes the findings of a survey on vacation jobs taken by students the previous year."},{"s":53.96,"e":59.12,"t":"It's spring and many of you may be thinking about arranging work for the long vacation."},{"s":59.48,"e":67.16,"t":"So on today's programme, Roger Anwell reports on a survey we conducted into the pleasures and problems of vacation jobs."},{"s":70.08,"e":76.22,"t":"Well, the first thing to say is that by far the majority of students we surveyed did just three types of jobs."},{"s":76.54,"e":79.86,"t":"All of these obviously had their advantages and disadvantages."},{"s":80.62,"e":83.34,"t":"Starting with stock-taking in supermarkets."},{"s":84.18,"e":87.74,"t":"The thing that students said they enjoyed most about this job was the travelling."},{"s":88.26,"e":94.42,"t":"They were often required to go to branches to do their stock takes and this was regarded as an interesting plus."},{"s":94.46,"e":102.06,"t":"The main negative, however, was that they tended to find the job tiring with long hours spent on their feet and climbing high shelves."},{"s":114.18,"e":115.76,"t":"That's the only way you can keep going."},{"s":127.6,"e":131.68,"t":"Lots of students named air conditioning as the best thing about office work."},{"s":132.34,"e":136.56,"t":"The downside, which many talked about, was wearing formal clothes."},{"s":137.14,"e":139.62,"t":"Obviously, this didn't go down too well with students."},{"s":140.04,"e":143.78,"t":"The advice most people gave was to select a large office."},{"s":144.44,"e":147.02,"t":"That way you have more variety of social contacts."},{"s":147.78,"e":150.34,"t":"Otherwise, the work can get very boring."},{"s":163.28,"e":166.42,"t":"It must have improved since my day, I must say."},{"s":167.06,"e":174.18,"t":"Anyway, the downside I did recognise, having to deal with difficult customers, especially in the heat when tempers get frayed."},{"s":221.84,"e":226.32,"t":"So, those were the findings from the survey on the most common student jobs."},{"s":226.98,"e":229.88,"t":"But not all student jobs have to be mundane and boring."},{"s":230.7,"e":236.54,"t":"One of the students who responded in our survey spoke at length about his amazing job as a zoo attendant."},{"s":237.06,"e":244.52,"t":"Peter Marshall had read about work opportunities on the zoo website and just went along with a friend to talk to someone in personnel."},{"s":245.1,"e":248.16,"t":"He was offered a job there and then, as easy as that."},{"s":266.0,"e":271.68,"t":"But he said it was well worth it because he thinks he's found his future career path as a result of this experience."},{"s":272.32,"e":279.22,"t":"He loved working on the educational side, in particular helping young kids understand about the animals in their natural environment."},{"s":293.72,"e":297.4,"t":"If you're interested in getting further information about the findings of the survey..."}],"3":[{"s":51.27,"e":53.15,"t":"Right then, are we ready?"},{"s":54.83,"e":57.19,"t":"And is someone taking notes for John?"},{"s":57.51,"e":59.01,"t":"He's at a tutorial, isn't he?"},{"s":58.87,"e":60.73,"t":"Yeah, I'll let him know what we agree."},{"s":61.61,"e":66.97,"t":"Okay, well first thing is, has anyone apart from me actually been in a study syndicate before?"},{"s":68.43,"e":70.61,"t":"What does it actually involve, Andy?"},{"s":71.03,"e":76.75,"t":"Well, the idea is that it's a way for us, for students to study together without a teacher."},{"s":85.67,"e":89.07,"t":"And I found I really learned a lot through having to teach it myself."},{"s":89.83,"e":91.69,"t":"It seemed a very good way to learn."},{"s":92.15,"e":95.57,"t":"And presumably it gives us the chance to share ideas as well."},{"s":95.73,"e":98.81,"t":"And you get fuller notes if you're all doing the reading."},{"s":100.45,"e":104.89,"t":"And as well as that, because of that, really, you can do, you know, much deeper research."},{"s":127.57,"e":130.73,"t":"I've drawn up the framework of a table which might be useful."},{"s":133.61,"e":136.97,"t":"For the first topic, I thought we could maybe do mountain building."},{"s":139.27,"e":141.21,"t":"Actually, would you mind if I did that?"},{"s":141.51,"e":143.07,"t":"I'm quite interested in it."},{"s":144.51,"e":147.43,"t":"So is May 9th OK for that?"},{"s":147.89,"e":149.51,"t":"I'll just write that down."},{"s":149.21,"e":151.09,"t":"And it's Bob for mountain building."},{"s":151.59,"e":155.43,"t":"And the following week, it can't be May 16th because of our tutorial."},{"s":155.59,"e":157.21,"t":"But what about the 17th?"},{"s":159.17,"e":161.33,"t":"And what about the next topic?"},{"s":161.71,"e":163.01,"t":"What would be the next priority?"},{"s":163.19,"e":168.89,"t":"Well, there's glaciated areas, but I don't want to do that."},{"s":170.41,"e":171.83,"t":"Actually, I don't mind having a bash."},{"s":172.25,"e":173.61,"t":"I did an assignment on them."},{"s":173.79,"e":175.49,"t":"Glaciated areas, Andy."},{"s":176.15,"e":178.05,"t":"Then we need someone to do rock formation."},{"s":179.21,"e":183.15,"t":"And John said he'd like to too, so you can put us both down for that."},{"s":183.93,"e":186.15,"t":"May 23rd would be best."},{"s":186.15,"e":188.31,"t":"Rock formation, Helen and John."},{"s":189.17,"e":191.91,"t":"That really only leaves one week before the exams."},{"s":192.09,"e":193.59,"t":"Shall we make it on the 30th?"},{"s":193.85,"e":195.65,"t":"I can't make it, I'm afraid."},{"s":197.49,"e":199.57,"t":"The exam's on June 3rd."},{"s":201.01,"e":203.45,"t":"Any ideas for a topic?"},{"s":203.61,"e":206.87,"t":"John said he wouldn't mind doing something on volcanoes."},{"s":247.62,"e":250.5,"t":"And how long should these presentations be?"},{"s":250.62,"e":252.48,"t":"Well, it's obviously up to us."},{"s":252.18,"e":255.04,"t":"In my experience, 30 minutes is about enough."},{"s":255.34,"e":257.04,"t":"Maybe a bit short."},{"s":257.24,"e":260.0,"t":"I'd have thought 40 minutes would be more like it."},{"s":260.34,"e":262.48,"t":"Well, shall we say 30 to 40 minutes?"},{"s":263.8,"e":265.74,"t":"And presumably time for questions?"},{"s":267.08,"e":269.94,"t":"Yes, together they usually take about 20 minutes."},{"s":270.12,"e":272.28,"t":"Where shall we get the information from?"},{"s":272.38,"e":274.12,"t":"Is it mainly lecture notes?"},{"s":274.24,"e":278.06,"t":"Well, actually, I suggest we avoid those because we already have all that information."},{"s":278.22,"e":280.14,"t":"I think it's better to go more deeply."},{"s":282.18,"e":285.22,"t":"And anything else we find in the library, any other books."},{"s":285.72,"e":288.54,"t":"And articles, you know, from the journals."},{"s":288.88,"e":291.26,"t":"And then, of course, there's lots of stuff on the internet."},{"s":291.18,"e":292.62,"t":"Yes, that's the sort of thing."},{"s":293.3,"e":295.12,"t":"And what about the presentations?"},{"s":295.2,"e":296.74,"t":"Will we just be talking?"},{"s":297.02,"e":299.22,"t":"Presumably we can't use slides."},{"s":302.58,"e":304.06,"t":"And the whiteboard, of course."},{"s":303.76,"e":307.58,"t":"And we can make photocopies of our notes so everyone can have a copy."},{"s":309.04,"e":310.56,"t":"So is there anything else?"}],"4":[{"s":21.27,"e":28.69,"t":"You'll hear part of a student presentation about a type of frog called the African Clawed Frog."},{"s":92.2,"e":101.76,"t":"The aim of our study was to look at how naturally occurring substances can be used to treat infections."},{"s":115.14,"e":124.1,"t":"So, before I describe our study in detail, let me give you a general description about this frog."},{"s":124.96,"e":131.4,"t":"Like most other frogs, the African Clawed Frogs have a smooth skin."},{"s":131.8,"e":137.06,"t":"This is one way you can distinguish them from toads, whose skin is rough."},{"s":136.92,"e":143.2,"t":"And they can change the color of their skin to blend in with their surroundings."},{"s":142.9,"e":148.02,"t":"The surface of their skin also has another feature."},{"s":148.54,"e":151.56,"t":"It's covered with a layer of mucus."},{"s":152.32,"e":159.9,"t":"This makes it hard for other creatures to pick them up, and so it provides protection against predators."},{"s":162.38,"e":172.8,"t":"Well, it depends on whether they're male or female, because the females, in this case, are a whole lot bigger than the males."},{"s":172.9,"e":180.84,"t":"A large-sized female may be 8 inches long, while the males are about half that size."},{"s":181.28,"e":184.1,"t":"So they're pretty small in comparison."},{"s":185.74,"e":188.12,"t":"What about their natural habitat?"},{"s":188.92,"e":198.94,"t":"As their name suggests, these frogs are native to Africa, and they're found in most parts of Africa, south of the Sahara Desert."},{"s":206.18,"e":207.74,"t":"They like still water."},{"s":208.46,"e":212.96,"t":"As far as the temperature of the water goes, they're not too fussy."},{"s":213.3,"e":215.34,"t":"It can be warm or cool."},{"s":225.26,"e":230.6,"t":"So they can live in brackish areas, such as marshes and estuaries."},{"s":244.4,"e":246.88,"t":"That's immediately fatal to them."},{"s":247.3,"e":252.04,"t":"And that's important to remember when they're being kept in captivity."},{"s":252.56,"e":258.7,"t":"You've got to be careful what kind of tank you use and what you put into the water."},{"s":258.4,"e":265.52,"t":"In their natural habitat, the frogs normally live in water the whole time."},{"s":265.88,"e":277.68,"t":"But in unfavorable conditions, such as drought, they can burrow into the mud and survive there for up to a year until conditions improve."},{"s":283.1,"e":287.36,"t":"As far as their diet is concerned, they're carnivorous."},{"s":287.44,"e":290.66,"t":"They eat other creatures they find in the water."},{"s":291.72,"e":299.12,"t":"And they're scavengers, which means they'll eat almost anything, living or dead."},{"s":299.9,"e":302.44,"t":"They've got huge appetites."},{"s":303.44,"e":313.9,"t":"Because the water they live in is often quite dirty and visibility is limited, they can't locate their food using their sense of sight."},{"s":320.3,"e":330.84,"t":"And they also have what's called a lateral line system on the sides of their bodies, which is sensitive to vibrations in the water."},{"s":343.34,"e":348.36,"t":"They don't have any teeth, so everything just goes straight down."},{"s":350.07,"e":358.37,"t":"Okay, well, although Xenopus started off in Africa, they're now quite widespread."},{"s":358.71,"e":366.25,"t":"One of the reasons for this is that a lot of people in the U.S. like keeping them at home as a pet."},{"s":366.85,"e":372.65,"t":"They're quite easy to look after and they can live for up to 20 years."},{"s":387.07,"e":391.39,"t":"So, they've been classified as a pest in these areas."},{"s":392.89,"e":398.81,"t":"But another very important use for the frogs is for research in laboratories."},{"s":415.61,"e":425.15,"t":"But also, the slippery mucus that covers their skin acts as an antibiotic, killing parasites and bacteria."},{"s":425.75,"e":429.87,"t":"And this is why we chose this frog for our research."},{"s":430.43,"e":434.37,"t":"So, let me describe the aim of our study."}]},"9":{"1":[{"s":3.16,"e":5.78,"t":"Good morning, Home Care Cleaning Agency."},{"s":7.68,"e":10.82,"t":"I'd like to arrange to have some cleaning done, please."},{"s":11.74,"e":13.7,"t":"Have you used our services before?"},{"s":13.88,"e":19.8,"t":"No, I haven't, but a friend of mine has often used your company and suggested I phone you."},{"s":21.22,"e":26.78,"t":"I'll just take some details from you and then you can let me know exactly what you would like done."},{"s":29.82,"e":32.0,"t":"I'm in the South West."},{"s":38.12,"e":43.04,"t":"No, I'd like to arrange to have someone come in once a week."},{"s":44.12,"e":47.32,"t":"Now, let's just get a bit of information about the house."},{"s":47.66,"e":49.46,"t":"How many bedrooms does it have?"},{"s":50.62,"e":52.32,"t":"Are they all double bedrooms?"},{"s":52.56,"e":60.38,"t":"Well, one of the bedrooms is quite small, so it's probably really two double rooms."},{"s":61.76,"e":64.4,"t":"We have the small bedroom set up as an office."},{"s":65.42,"e":69.26,"t":"And just a standard kitchen, lounge, dining room and bathroom?"},{"s":69.7,"e":72.6,"t":"Well, actually, we don't have a separate dining room."},{"s":72.8,"e":74.4,"t":"It's a kitchen-diner."},{"s":74.76,"e":79.74,"t":"Then there's the lounge, and as well as that, we have a family room."},{"s":79.86,"e":81.82,"t":"Oh, and two bathrooms."},{"s":140.52,"e":143.08,"t":"That's all I need to know about the house itself."},{"s":143.34,"e":150.6,"t":"Now, what we do is we offer a basic cleaning service and then you let us know about anything extra you'd like cleaned."},{"s":152.4,"e":156.04,"t":"And what does the basic service include?"},{"s":155.74,"e":161.38,"t":"We clean all the floors and surfaces and do a basic clean in the kitchen and bathroom."},{"s":161.74,"e":163.78,"t":"Okay, that sounds good."},{"s":164.14,"e":166.14,"t":"And do you clean windows?"},{"s":166.26,"e":168.28,"t":"Well, I'm afraid we don't do that."},{"s":168.06,"e":170.02,"t":"Health and safety regulations."},{"s":170.2,"e":172.76,"t":"But we do offer other special services."},{"s":172.82,"e":175.8,"t":"We can put clean sheets on the beds, for example."},{"s":176.8,"e":178.88,"t":"Or we can clean out your fridge."},{"s":179.02,"e":180.58,"t":"A lot of people like that done."},{"s":180.28,"e":185.12,"t":"I'm not so worried about that, but I would like the sheets changed."},{"s":185.0,"e":186.3,"t":"That's no problem."},{"s":187.66,"e":189.14,"t":"What about the carpet?"},{"s":189.2,"e":193.12,"t":"As well as the standard vacuum, we can shampoo it if you want."},{"s":194.78,"e":197.9,"t":"We've got young children, so it gets pretty dirty."},{"s":198.24,"e":200.14,"t":"I haven't had it done for six months."},{"s":200.64,"e":203.4,"t":"It really needs doing more often than that."},{"s":203.5,"e":208.92,"t":"You can have it done every month if you like, but three months is what we usually recommend."},{"s":209.12,"e":210.76,"t":"That sounds good."},{"s":211.36,"e":213.2,"t":"The only other thing is the washing."},{"s":213.62,"e":215.2,"t":"Do you do laundry work?"},{"s":217.52,"e":219.22,"t":"What exactly would you like done?"},{"s":219.7,"e":223.42,"t":"Well, it's no problem to put a load of washing in the machine."},{"s":224.16,"e":227.04,"t":"But I would like to have the ironing done."},{"s":228.1,"e":231.58,"t":"And would you like the washing put away in drawers or wardrobes?"},{"s":231.64,"e":233.06,"t":"No, it's okay."},{"s":233.0,"e":235.44,"t":"You can just leave everything out and fold it up."},{"s":236.68,"e":242.0,"t":"Now, I'll just set up an account for you and I'll take down some of your details."},{"s":242.54,"e":244.72,"t":"First of all, what's your full name?"},{"s":245.12,"e":247.18,"t":"It's Rose Kelly."},{"s":247.38,"e":250.7,"t":"And could I have your home address, please, Mrs Kelly?"},{"s":268.62,"e":270.66,"t":"It doesn't really matter."},{"s":271.14,"e":273.66,"t":"Not Monday, but any other day."},{"s":274.02,"e":275.74,"t":"Okay, let's see."},{"s":275.86,"e":281.76,"t":"We have a cleaner in your area later on Thursday, so shall we go for that day?"},{"s":281.92,"e":286.14,"t":"We could have someone there by about 9.30 in the morning."},{"s":287.46,"e":288.98,"t":"Yes, that's fine."},{"s":289.64,"e":294.22,"t":"And do you charge an hourly rate or a total for the whole job?"},{"s":294.22,"e":296.52,"t":"No, we charge by the hour."},{"s":296.22,"e":299.92,"t":"It will work out to about $25 per hour."},{"s":300.52,"e":302.12,"t":"Oh, that's quite reasonable."},{"s":302.9,"e":304.8,"t":"I thought it might be closer to $30."},{"s":305.74,"e":308.36,"t":"And how long do you expect it to take?"},{"s":308.5,"e":314.62,"t":"Well, you said the house isn't large, so I'd guess no more than three hours at the most."},{"s":314.98,"e":320.74,"t":"We can occasionally finish a three-bedroom in two and a half, but that's probably not too realistic."},{"s":321.04,"e":323.1,"t":"Right, that sounds good."},{"s":323.36,"e":325.98,"t":"Thank you very much."},{"s":325.78,"e":327.98,"t":"And we'll have someone there next week."}],"2":[{"s":45.46,"e":51.46,"t":"Well, first of all, I'll give you a bit of background to the museum and then tell you about some of the galleries."},{"s":73.68,"e":77.46,"t":"Now, the actual museum building itself is quite interesting."},{"s":90.9,"e":96.5,"t":"The museum's built in a very similar style to the railway station, which was constructed at around the same time."},{"s":106.38,"e":114.5,"t":"Construction of the museum began in 1888 with a large team of carpenters, stonemasons and builders."},{"s":115.48,"e":118.64,"t":"Then, in recent years, it's been extensively refurbished."},{"s":129.12,"e":134.26,"t":"In particular, the beautiful wrought iron staircase, which was brought back to its former glory."},{"s":135.3,"e":141.22,"t":"Unfortunately, the museum's original tiled floor had to be replaced with new tiles of a similar design."},{"s":142.52,"e":148.36,"t":"It was a very expensive project, and since we don't charge admission fees, we had to find other ways of funding it."},{"s":159.08,"e":165.58,"t":"However, we do also depend on donations from people living in the area for the ongoing maintenance of the building."},{"s":166.6,"e":171.28,"t":"So, how will the museum mainly be spending its money in the next five years?"},{"s":172.06,"e":177.66,"t":"We already work with schools and colleges, helping people get a better understanding of all the creative disciplines."},{"s":190.28,"e":196.0,"t":"Of course, it would be wonderful to purchase new objects for the museum, but we simply don't have the space at the moment."},{"s":210.32,"e":217.42,"t":"Of course, you can pick up leaflets about the exhibits in most of the galleries too, but you'll only get a basic introduction from those."},{"s":218.22,"e":225.4,"t":"We're also working to update our website so that it provides more background on the exhibits, but that's still at the planning stage."},{"s":263.17,"e":267.75,"t":"Okay, now let me just tell you a bit about what's on at the moment."},{"s":268.33,"e":274.99,"t":"Well, we're very well known for our collection of 18th century paintings, both oils and watercolours."},{"s":275.39,"e":282.45,"t":"Some of these are English landscapes and portraits, but we also have paintings by other European artists who were working during this period."},{"s":283.11,"e":290.31,"t":"If you're interested in art that's a bit nearer home, the Farnley Collection is a set of drawings by Paul Farnley."},{"s":290.73,"e":298.05,"t":"He was born in Ireland, but he came to work here in the city in the early 20th century and then made it his home."},{"s":309.09,"e":313.73,"t":"On a more practical note, we have a display of kitchen appliances which might interest you."},{"s":314.09,"e":317.43,"t":"These are the sorts of things you wouldn't normally expect to see in a museum."},{"s":318.03,"e":324.95,"t":"There's an electric potato peeler from the 1970s which sold really well at the time, but no one's got one now."},{"s":325.31,"e":331.65,"t":"There are lots of other similar appliances which must have seemed like great ideas at the time, but which never took off."},{"s":332.59,"e":335.17,"t":"You might also like to visit the Fashion Gallery."},{"s":347.37,"e":350.17,"t":"Okay, so if anyone's got any questions..."}],"3":[{"s":44.11,"e":45.81,"t":"Hi Francis, Sam."},{"s":46.51,"e":52.01,"t":"So, how did you go with applying the different theoretical business tools for the report I asked you to write?"},{"s":51.71,"e":57.63,"t":"It was interesting and made us really focus on which tool was best to use when analysing a business."},{"s":58.69,"e":60.63,"t":"So, tell me what you found out."},{"s":60.75,"e":63.45,"t":"We liked the theory behind pest analysis."},{"s":63.89,"e":71.73,"t":"That's political, economic, social and technological, although we're not sure if it was very applicable to our case."},{"s":72.25,"e":77.53,"t":"Some of the other groups had studies for which it worked really well and they said it was easy to use."},{"s":77.67,"e":82.71,"t":"But I felt it focused too much on the big picture and was unsuitable for our company."},{"s":84.11,"e":87.45,"t":"On the other hand, I enjoyed using the drill-down method."},{"s":87.59,"e":93.49,"t":"It was painstaking to do and we seemed to be working on it for ages, but the results were worth waiting for."},{"s":94.41,"e":97.67,"t":"I liked the way it eventually broke down complex problems."},{"s":98.51,"e":101.25,"t":"I much preferred doing the PMI analysis."},{"s":101.45,"e":107.71,"t":"It was so straightforward to break down into its three components – plus, minus and interesting implications."},{"s":107.41,"e":111.71,"t":"You just needed to brainstorm these components and then write them up."},{"s":111.83,"e":113.15,"t":"Fast and effective."},{"s":113.35,"e":115.59,"t":"And it didn't make your brain hurt doing it."},{"s":116.73,"e":118.91,"t":"And you don't need any special training at all."},{"s":118.79,"e":120.37,"t":"Anyone can use it."},{"s":121.27,"e":125.11,"t":"So, was there any tool that you thought was superior to the others?"},{"s":125.41,"e":131.95,"t":"In my opinion, the one tool that is critical to business, especially for larger companies, is Pareto analysis."},{"s":131.65,"e":140.59,"t":"If they applied Pareto analysis, they would see that by focusing on the critical 20% of their problems, they could generate 80% of the benefits."},{"s":140.97,"e":144.91,"t":"This would allow them to work faster and it also reduces their workload."},{"s":145.33,"e":148.11,"t":"It's all about finding out what their basic problems are."},{"s":148.39,"e":153.31,"t":"I agree with Francis about Pareto, but my favourite was the SWOT analysis."},{"s":153.53,"e":161.71,"t":"You know, looking at the company's strengths, weaknesses, opportunities and threats, as it can be used in so many different situations."},{"s":162.11,"e":166.49,"t":"It works in large and small companies and even down to departmental level."},{"s":166.71,"e":168.35,"t":"It was great for our case study."},{"s":223.66,"e":229.62,"t":"I've read your draft report, but can you tell me a bit more about that company you focused on?"},{"s":229.32,"e":237.04,"t":"Well, the company we used in our study was a manufacturing company who have relied on distributors to take their product to the end user."},{"s":237.64,"e":242.06,"t":"We did some analysis examining the possibility of them distributing their own products."},{"s":242.1,"e":244.04,"t":"We initially looked at their strengths."},{"s":244.24,"e":248.7,"t":"The company, although it is small, is well known and has a very good reputation."},{"s":249.22,"e":255.1,"t":"The management are very committed to increasing the company profits and they are confident this move would be successful."},{"s":256.6,"e":262.82,"t":"And the company has quite a lot of staff who have previously worked for distribution companies, so the knowledge is already there."},{"s":263.02,"e":268.04,"t":"That was something we didn't expect to find and is probably going to help them the most to achieve their goals."},{"s":268.12,"e":271.86,"t":"I was quite impressed by some of the opportunities you detailed."},{"s":272.48,"e":277.2,"t":"I did think you missed something quite pertinent to their future growth, however."},{"s":278.7,"e":282.74,"t":"You didn't consider the potential for establishing an offshore division."},{"s":282.44,"e":287.32,"t":"You talked about the company negotiating better terms with its suppliers."},{"s":298.74,"e":300.38,"t":"That's a good point."},{"s":301.18,"e":304.2,"t":"So what did you think about the threats we identified?"},{"s":304.4,"e":305.98,"t":"I thought you did a good job."},{"s":306.02,"e":314.12,"t":"I was really pleased to see that you considered how the government's planned environmental policy could really affect the viability of this venture."},{"s":314.92,"e":321.18,"t":"With this law being introduced next year, they might need to find new ways of using their existing technology."},{"s":321.82,"e":327.86,"t":"It's easy to identify what your competitors are doing, but it's the bigger picture that often gets ignored."},{"s":328.7,"e":331.7,"t":"So, Sam, what did you learn from this assignment?"},{"s":333.1,"e":338.16,"t":"I guess I hadn't realised how much time it takes to ensure your company survives and profits."},{"s":338.66,"e":344.44,"t":"It was great to study the different tools in books, but applying them in the real world was much harder than I thought."},{"s":344.82,"e":346.54,"t":"It was a great learning experience."},{"s":346.7,"e":348.82,"t":"I'm glad I could make your assignment relevant."},{"s":349.6,"e":351.7,"t":"I'm basically happy with your report."},{"s":352.08,"e":358.94,"t":"You've got the format correct with the necessary headings, etc., and you've got sufficient details under the different headings."},{"s":359.52,"e":364.18,"t":"Just remember to state whether or not you think the company should go ahead with the new venture."},{"s":363.88,"e":366.72,"t":"But you've done a good job so far."}],"4":[{"s":74.98,"e":84.08,"t":"I'd like to give you a brief overview of a research project I've been working on as part of a team of four."},{"s":93.18,"e":99.98,"t":"We focused on graduates from the course in Business Management, since this is one of the most popular and long-established courses."},{"s":100.52,"e":103.66,"t":"We decided to use two different data-gathering methods."},{"s":127.02,"e":128.68,"t":"So, what did we find?"},{"s":139.26,"e":141.8,"t":"That was 32%, almost a third."},{"s":142.2,"e":149.08,"t":"Of the rest, a very small proportion were unemployed, just 4%, and all the rest were in employment."},{"s":162.38,"e":165.66,"t":"The majority said that their expectations had been fulfilled."},{"s":197.48,"e":201.54,"t":"They highlighted the fact that they developed the ability to work as members of a team."},{"s":201.84,"e":209.34,"t":"Another skill which they cited as valuable was that of personal organisation, things like meeting deadlines, time management, and so on."},{"s":209.8,"e":215.72,"t":"And finally, a lot of them said that what they'd learned about approaches to problem-solving had been very useful."},{"s":221.18,"e":225.12,"t":"To our surprise, the thing that was mentioned most often here was presentations."},{"s":233.62,"e":238.28,"t":"The reason given for this was that they felt they weren't trained how to do it properly."},{"s":238.92,"e":243.28,"t":"And the second thing that got very negative feedback was work on essay writing."},{"s":243.42,"e":248.7,"t":"Most people thought this was unnecessary, and that it would have been better to work on report writing."}]},"10":{"1":[{"s":89.73,"e":91.17,"t":"Thanks for coming round."},{"s":97.47,"e":100.99,"t":"So, um, we're at 15 Hill Street?"},{"s":103.87,"e":106.83,"t":"And then I need to write down your contact information."},{"s":106.53,"e":108.47,"t":"Just for the office, you know."},{"s":120.07,"e":123.39,"t":"And your phone number, I've got that somewhere."},{"s":123.71,"e":129.29,"t":"Yes, 027 584 6613."},{"s":134.55,"e":137.51,"t":"Well, let's go into the kitchen first."},{"s":138.71,"e":140.97,"t":"So, you see, it's quite dark in here."},{"s":146.25,"e":150.25,"t":"So what we've decided is the window is too small."},{"s":150.33,"e":151.83,"t":"We'd like a larger one."},{"s":151.83,"e":153.17,"t":"That shouldn't be a problem."},{"s":152.87,"e":155.95,"t":"And is there anything else you'd like done in the kitchen?"},{"s":156.17,"e":163.43,"t":"Well, at this time of year, I mean, I shouldn't complain really, but I wish it wasn't so hot in here."},{"s":163.71,"e":165.69,"t":"Is there anything you can do about that?"},{"s":174.61,"e":177.73,"t":"Well, if we walk through into the bathroom."},{"s":178.05,"e":181.91,"t":"The thing is, when my father's staying, he can't use the bath."},{"s":182.11,"e":186.61,"t":"So I thought here, on the back wall, I'd like you to fit a shower."},{"s":187.87,"e":189.33,"t":"Shouldn't be too hard."},{"s":189.55,"e":193.25,"t":"I'll get you some brochures, because there are a few ways of doing that."},{"s":194.15,"e":196.79,"t":"Now, those tiles on the wall look new."},{"s":196.97,"e":198.27,"t":"So do you want to keep those?"},{"s":198.35,"e":202.05,"t":"Yes, the tiles are new, but actually my husband doesn't like them."},{"s":202.39,"e":205.15,"t":"We want to change to those very small ones."},{"s":205.33,"e":207.53,"t":"But do I have to choose a colour now?"},{"s":207.53,"e":209.09,"t":"You can do that later."},{"s":209.09,"e":211.15,"t":"I'll get some charts for you to look at."},{"s":258.73,"e":260.05,"t":"Let's walk outside."},{"s":260.65,"e":263.21,"t":"I need to show you some things outside the house."},{"s":266.19,"e":267.97,"t":"And the fence looks in good condition."},{"s":269.09,"e":270.97,"t":"But the thing is the gate."},{"s":272.45,"e":274.47,"t":"You have to bend down to open it."},{"s":274.31,"e":275.81,"t":"We need something that's higher."},{"s":278.19,"e":280.57,"t":"Then the other thing is the garage here."},{"s":280.83,"e":282.39,"t":"We had a break-in, actually."},{"s":289.07,"e":290.59,"t":"I'll replace that, shall I?"},{"s":291.51,"e":297.51,"t":"Then also, if you step back here and look up on the roof, you can see that it's damaged."},{"s":298.05,"e":300.47,"t":"Did that happen in the storm a couple of weeks ago?"},{"s":301.61,"e":303.59,"t":"I'll get up there and take a look at that then."},{"s":308.39,"e":311.29,"t":"I can see that your rain gutter is broken as well."},{"s":312.91,"e":316.17,"t":"Well, I'll need to replace it, maybe with a steel one."},{"s":317.33,"e":319.53,"t":"No, plastic will be fine, thanks."},{"s":321.59,"e":323.73,"t":"And that's everything, I think."},{"s":323.99,"e":326.15,"t":"Is there any other information you need?"},{"s":326.07,"e":327.61,"t":"What about a start date?"},{"s":327.85,"e":334.61,"t":"Well, I'm completely booked all April, and I've got a job on May the 5th."},{"s":334.33,"e":335.77,"t":"That'll be a few days."},{"s":336.01,"e":338.27,"t":"So, let's say May the 8th."},{"s":339.45,"e":341.89,"t":"Now, what about a key, in case you're out?"},{"s":342.03,"e":343.55,"t":"We have a security code."},{"s":344.81,"e":346.79,"t":"It's a mix of letters and numbers."}],"2":[{"s":66.15,"e":71.01,"t":"I'm Susan Meyer, Trail Warden for the McFaddin Hiking and Nature Trail."},{"s":71.25,"e":73.75,"t":"Let me tell you a bit about the trail."},{"s":74.53,"e":79.61,"t":"The trail is 25 miles long, running roughly east to west."},{"s":79.31,"e":85.53,"t":"To hike it, you may start at either end of the trail or in between."},{"s":100.01,"e":107.57,"t":"For hikers coming from Johnson City, there's a shuttle bus to each of the two end points every morning and evening."},{"s":115.69,"e":127.99,"t":"At one-mile intervals along the trail, there are rest stations providing picnic areas, water, toilets, and places where you can recharge your electronic devices."},{"s":140.73,"e":144.17,"t":"There are several distinct sections of trail."},{"s":144.95,"e":152.67,"t":"The Red Rock Walk offers a superb opportunity to study a huge variety of vegetation along the way."},{"s":153.91,"e":158.23,"t":"There's lots to look at, though you can't see great distances."},{"s":159.45,"e":169.23,"t":"Birds are actually hard to spot, but with a pair of binoculars and at certain times of day, you may see some rare varieties."},{"s":170.75,"e":178.15,"t":"The River Walk comprises about five miles of trail winding along the bank of the Malder River."},{"s":183.65,"e":190.61,"t":"The river does freeze over, and the snow can accumulate, but that doesn't always discourage visitors."},{"s":191.49,"e":198.75,"t":"Sometimes, though, if the weather conditions are really unsuitable, we might have to close this walk to the public."},{"s":199.69,"e":205.69,"t":"But often it can get crowded with hikers who've discovered the attraction of the area."},{"s":251.67,"e":258.35,"t":"Now let me tell you about the Halfway Hostel, located approximately midway along the trail."},{"s":258.93,"e":263.83,"t":"It has a range of facilities available to help make your walking experience memorable."},{"s":263.53,"e":269.37,"t":"Let me give you some information about the various facilities available there."},{"s":270.13,"e":277.97,"t":"Of course, there are beds in dormitories for use at a very reasonable $7 per person weekdays or weekends."},{"s":290.45,"e":297.69,"t":"There are two family rooms, accommodating six people each, with private bathrooms."},{"s":308.33,"e":316.39,"t":"A popular facility that we've recently added is coin-operated washing machines for your clothes."},{"s":329.17,"e":338.45,"t":"The hostel serves two meals a day, breakfast at $4 and dinner at $8, the same for adults and kids."},{"s":339.09,"e":344.81,"t":"There's always a vegetarian and a non-vegetarian option, depending on your preferences."},{"s":346.09,"e":350.57,"t":"We do ask you to give a hand with serving and cleaning up after meals."},{"s":382.67,"e":384.55,"t":"So, if you think..."}],"3":[{"s":59.37,"e":61.33,"t":"Hello, Pam, Jason."},{"s":62.09,"e":64.45,"t":"Thanks for coming to discuss your marketing project."},{"s":64.69,"e":68.03,"t":"I've read your proposal and outline, so let's go over it."},{"s":69.93,"e":75.93,"t":"You've chosen the topic of food packaging, so what did you want to get out of doing this project?"},{"s":75.63,"e":83.29,"t":"We decided if we did our project on packaging, we might find some practical tips on how a business could make more money."},{"s":83.71,"e":88.83,"t":"After all, we're business admin students and that's the ultimate reason we're on the course, isn't it?"},{"s":89.25,"e":93.14,"t":"So, although we know the impact of packaging on the environment is important..."},{"s":93.23,"e":97.63,"t":"We feel the government regulations are pretty strict already in that area."},{"s":99.11,"e":106.19,"t":"Now you've decided to look specifically at the packaging of food, what do you think the main issue is for shoppers these days?"},{"s":134.63,"e":138.05,"t":"And you've chosen to concentrate on big supermarket chains."},{"s":138.03,"e":141.27,"t":"Why not look at local stores or even convenience stores?"},{"s":160.61,"e":168.23,"t":"Of course, the supermarkets do account for most food sales around here, but that wasn't our reason for choosing them."},{"s":168.65,"e":173.55,"t":"Speaking of this area, you know the food buying choices here are quite unusual."},{"s":183.29,"e":188.63,"t":"And although the education level is pretty high, that doesn't seem very important either."},{"s":188.33,"e":195.33,"t":"I guess it's because we got people from all over the world living here, with all the foreign students at university."},{"s":196.87,"e":200.23,"t":"Our supermarkets cater for a huge diversity of cultures."},{"s":200.65,"e":207.37,"t":"In our survey of the literature, I was struck by what shoppers say is most important to them when they buy."},{"s":207.75,"e":214.23,"t":"I would have thought how much the buyer had to pay would be the key, but that doesn't appear to be the case."},{"s":219.53,"e":224.37,"t":"Whether or not the food is good for you is pretty low down on the customer's priorities."},{"s":268.35,"e":271.71,"t":"Let's discuss the practical experiment you're planning."},{"s":271.41,"e":276.75,"t":"You're going to design the box for a new breakfast cereal which you'll try to market."},{"s":277.01,"e":286.05,"t":"Not in reality, of course, but by showing different designs to some of your fellow students on a computer, a kind of virtual reality supermarket."},{"s":286.31,"e":289.25,"t":"And the students will choose the design that appeals most."},{"s":289.79,"e":291.69,"t":"Let's talk through the experiment, okay?"},{"s":293.35,"e":298.31,"t":"Now, the number of different designs you're proposing to show each student is two."},{"s":298.73,"e":301.35,"t":"If I were you, I'd make it at least four."},{"s":301.41,"e":306.19,"t":"That way you can examine their reaction to more variety in the kinds of packaging."},{"s":306.39,"e":308.07,"t":"Okay, good idea."},{"s":308.31,"e":310.61,"t":"We do have several more designs."},{"s":311.37,"e":315.03,"t":"Now, we've got a sample from our class of about 20."},{"s":318.31,"e":321.59,"t":"Try talking to the assistant in the business studies department."},{"s":321.83,"e":325.41,"t":"He can sort out how to recruit some more from other classes for you."},{"s":335.17,"e":340.19,"t":"Go back and look over what I said about the practical realities of conducting experiments."},{"s":340.45,"e":342.17,"t":"Okay, we can do that."},{"s":342.47,"e":347.03,"t":"We're going to ask each student to choose the one design they think is best."},{"s":347.57,"e":350.75,"t":"But how will we know why they chose that one?"},{"s":351.23,"e":354.59,"t":"Well, don't just rely on oral prompts."},{"s":354.93,"e":356.95,"t":"Give them a series of written questions."},{"s":356.93,"e":358.43,"t":"That way you'll have hard data."},{"s":359.53,"e":362.05,"t":"But what about analyzing the data?"},{"s":362.65,"e":369.59,"t":"Well, we've got an excellent computer program to gather it all together, but we still need to interpret it ourselves."},{"s":369.87,"e":373.27,"t":"So, we'll need to give ourselves a few more days for that."},{"s":374.43,"e":376.37,"t":"Anyway, it's all looking good."}],"4":[{"s":40.42,"e":44.58,"t":"You may also like to suggest some other likely changes yourselves."},{"s":63.1,"e":69.82,"t":"The invention of computers represents an enormous leap forward in the field of human endeavor."},{"s":82.48,"e":94.4,"t":"In the future, the computational revolution is certain to be generally recognized as a transformation as significant as, say, the industrial revolution."},{"s":108.66,"e":116.14,"t":"There was considerable agreement that people will increasingly perceive these computer systems as intelligent."},{"s":134.3,"e":142.0,"t":"Without going into further detail about this at this point, let's turn to what predictions psychologists had to make."},{"s":141.7,"e":149.82,"t":"Their key point was that psychological research would inevitably become increasingly varied."},{"s":150.22,"e":156.22,"t":"It would move into such areas as behavioral economics and social neuroscience."},{"s":174.12,"e":185.06,"t":"At the same time as they broaden their horizons, psychologists will also intensify their search to discover what exactly determines how we act."},{"s":195.36,"e":199.46,"t":"There should be some fascinating discoveries coming to light very soon."},{"s":203.61,"e":209.99,"t":"Another field that is currently undergoing enormous changes is that of genetics."},{"s":210.87,"e":217.33,"t":"It is not new to suggest that average life expectancy is likely to continue rising in most countries."},{"s":217.85,"e":229.09,"t":"However, today geneticists emphasize that it is vital that the increasing number of the elderly in society must take quality of life into account."},{"s":230.01,"e":232.89,"t":"So how will genetics help this to happen?"},{"s":233.61,"e":241.43,"t":"To start with, they hope to develop technologies that can sequence each person's genome extremely cheaply."},{"s":242.09,"e":251.47,"t":"This information about our DNA enables health care providers to predict our likelihood of suffering from any particular disease."},{"s":276.65,"e":282.05,"t":"The final subject area that I wish to bring to your attention is that of zoology."},{"s":282.81,"e":287.63,"t":"Once again, computers and technology have a key role to play here."},{"s":288.03,"e":294.59,"t":"Experts comment specifically on the importance of satellites for future developments in this field."},{"s":295.49,"e":300.75,"t":"These enable people to explore the world from their homes, offices, and schools."},{"s":328.09,"e":334.89,"t":"They hope that we will learn to connect our minds to our hearts and apply this new knowledge to help protect our planet."}]}};
